(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-microscaling-data-formats-for-deep-l-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-1\">一 · 一个被带宽掐住脖子的在线服务现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-2\">二 · 旧方案一：整张量共享一个缩放因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-3\">三 · 旧方案二：逐通道／逐元素缩放与它的元数据税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-4\">四 · 为什么非改不可：三个约束同时收紧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-5\">五 · 旧栈的算子耦合：格式一变，整条链路都要动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-6\">六 · 落点：块大小是第一个要定的工程参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-7\">七 · 块缩放语义落地时的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-8\">八 · 负载形态决定块缩放格式的收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-9\">九 · 输入长度分布与批大小如何塑造量化粒度选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-10\">十 · SLO 与长尾：延迟预算如何反向约束格式选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-11\">十一 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-12\">十二 · 方案反向限制负载的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-13\">十三 · 块缩放格式在请求形态下的边界：元数据比例、离群块与 SLO 长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-14\">十四 · 从格式语义到算子契约：块缩放如何进入矩阵乘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-15\">十五 · 数据类型谱系：FP16/BF16/FP8/NVFP4 各自承担什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-16\">十六 · 累加精度与误差传播：FP32 累加器不是可选项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与块缩放的咬合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-18\">十八 · 算子实现中的三个具体咬合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-19\">十九 · 块缩放语义在算子边界上的失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-20\">二十 · 显存账本的三本分册：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-21\">二十一 · 分页与块对齐：页大小必须被块大小整除</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-22\">二十二 · 带宽瓶颈的定位：解码步是 KV 读带宽的函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-23\">二十三 · 压缩、复用与卸载：KV 的三级台阶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-24\">二十四 · 可复算的显存预算：从位宽到 GB 的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-25\">二十五 · 块内离群值与账本误差：格式语义决定预算可信度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-26\">二十六 · 块缩放格式的显存账本：从格式语义到 KV 预算的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-27\">二十七 · 块缩放语义如何改写批调度的成本模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-28\">二十八 · 连续批处理与 chunked prefill 的块级耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-29\">二十九 · 优先级、抢占与 KV 的低精度重写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-30\">三十 · 分离式预填/解码的格式不对称</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-31\">三十一 · 尾延迟的压缩手段与格式代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-32\">三十二 · 块缩放语义如何约束调度粒度与抢占代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-33\">三十三 · 切分维度与通信原语的对应关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-34\">三十四 · 块缩放格式如何改变通信账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-35\">三十五 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-36\">三十六 · NIXL 与传输层：把 KV 当一等公民搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-37\">三十七 · 并行组合下的数值一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-38\">三十八 · 容量规划中的通信预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-39\">三十九 · 块缩放语义在并行切分下的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-40\">四十 · 精度塌陷：块内离群值如何吃掉尾数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-41\">四十一 · OOM 与批抖动：元数据、KV 与瞬时峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-42\">四十二 · 尾延迟：缩放读取与反量化的串行代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-43\">四十三 · 静默降级：语义不一致与多层累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-44\">四十四 · 监控与回滚的工程闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-45\">四十五 · 块缩放格式的失效边界：从离群块到静默精度漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-46\">四十六 · 论文的基准口径：格式定义不是性能声明</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-47\">四十七 · 硬件档位与 batch／并发：论文未给的三个空格</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-48\">四十八 · 指标口径：TTFT／TPOT／吞吐／显存／功耗各自能挂什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-49\">四十九 · 哪些提升不可比：四类常见误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-50\">五十 · 失败模式如何进入基准读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-51\">五十一 · 工程判断：把论文放在语义层，把数字留给自测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-52\">五十二 · 块缩放格式的基准口径：哪些数字能比，哪些不能</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-53\">五十三 · 迁移到非 Transformer 主干：块统计假设先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-54\">五十四 · 迁到视觉与扩散负载：激活分布与时间步耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-55\">五十五 · 迁到长上下文与 KV cache：块粒度与缓存布局冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-56\">五十六 · 规模上限：块大小、位宽与算子融合深度的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-57\">五十七 · 不适用的边界：格式语义不等于吞吐收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-microscaling-data-formats-for-deep-l-2023-sec-58\">五十八 · 块缩放格式迁移到别的负载时，先看离群值结构与块边界是否对齐</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输入张量按固定块大小切分，逐块统计绝对值最大值以推导共享缩放因子。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">缩放因子编码为 E8M0 或 FP8 指数形式，块内元素量化为 FP4…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重与激活分别按块量化后送入矩阵乘算子，算子内部按块反量化或融合缩放累…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">注意力与归一化等逐元素算子沿用块缩放语义，避免全局缩放被离群值拉偏。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出按块重新量化写回，供下一层或 KV 缓存以低精度存储与传输。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-1\">一 · 一个被带宽掐住脖子的在线服务现场</h3>\n<p>设想一个图像生成推理服务：多卡节点上常驻一个数十亿参数级的扩散主干，前端网关按秒级节奏灌入请求，每个请求要跑几十步去噪，每步都要把整份权重从 HBM 搬到 SM 里做一次矩阵乘。工程上最先撞墙的往往不是算力，而是搬运：权重张量在显存里占着固定的一块，每一步都要被完整读一遍，读的速度由 HBM 带宽封顶。把这一步的代价写成式子，单步权重读取时间近似为</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\frac{W_{\\text{bytes}}}{\\text{BW}_{\\text{eff}}},\\qquad W_{\\text{bytes}} = N_{\\text{param}}\\times b_{\\text{eff}}$$</div>\n<p>其中 $b_{\\text{eff}}$ 是每参数实际占用的比特数（含缩放元数据）。在 FP16 下 $b_{\\text{eff}}=16$，一个 7B 级主干单步就要搬十几 GB；扩散模型几十步串行，端到端延迟被这条搬运链锁死。并发一上来，KV 缓存与激活又抢同一块带宽，尾延迟抖动立刻显形。这就是这篇论文出场时的现场：不是精度不够用，而是位宽降不下去——降得粗暴就掉画质，降得精细就付不起元数据。</p>\n<p>具体到一个工程判断：当服务 SLO 要求 P99 延迟落在某个区间、而单步权重读取已占去大半预算时，唯一的结构性出路是压缩 $b_{\\text{eff}}$。而 $b_{\\text{eff}}$ 的下降不是免费的，它由格式定义决定，这正是 Microscaling 要解决的问题。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-2\">二 · 旧方案一：整张量共享一个缩放因子</h3>\n<p>论文之前最省事的做法是 per-tensor 量化：整个权重张量共用一个缩放因子 $s$，元素存成 INT8 或 FP8。量化与反量化语义简单，</p>\n<div class=\"formula\">$$q_i=\\mathrm{round}\\left(\\frac{x_i}{s}\\right),\\quad s=\\frac{\\max_j|x_j|}{q_{\\max}}$$</div>\n<p>元数据只有一个标量，显存开销几乎为零，算子实现也最轻。痛点在统计粒度：$s$ 被张量里绝对值最大的那个元素钉死。深度网络权重与激活的分布是重尾的，少数离群值把 $s$ 拉高，其余绝大多数元素除以 $s$ 后落在量化格点最稀疏的低位区间，有效尾数被白白浪费。对扩散模型尤其致命——去噪各步的激活分布随 timestep 漂移，一个全局缩放无法同时适配早期高噪声步与后期细节步，画质在细节频段先崩。</p>\n<p>系统代价上，per-tensor 的收益是确定的：$b_{\\text{eff}}$ 从 16 降到 8 附近，权重读取时间近似减半，显存占用同比例下降。但它把精度风险集中到一个标量上，一旦某层出现离群通道，整层精度塌陷，且这种塌陷在多层串联后累积，表现为生成结果的系统性偏差而非局部噪声。工程上常见的补救是混合精度回退——敏感层保留 FP16——但这又让 $b_{\\text{eff}}$ 回升，带宽收益被侵蚀，且回退层的选择依赖人工经验，服务化时难以稳定复现。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-3\">三 · 旧方案二：逐通道／逐元素缩放与它的元数据税</h3>\n<p>为缓解离群值，另一条路是 per-channel 或 per-element 缩放：每个输出通道一个 $s$，极端情况下每个元素一个 $s$。统计粒度细了，动态范围适配好了，但元数据随粒度线性膨胀。以 per-channel 为例，一个 $K\\times N$ 的权重矩阵要存 $N$ 个缩放因子；若缩放用 FP16 编码，元数据比特占比为</p>\n<div class=\"formula\">$$\\rho_{\\text{meta}}=\\frac{N\\times 16}{K\\times N\\times b_{\\text{elem}}+N\\times 16}=\\frac{16}{K\\,b_{\\text{elem}}+16}$$</div>\n<p>$K$ 较小时（如注意力里的小投影矩阵、卷积的窄通道），$\\rho_{\\text{meta}}$ 迅速上升，$b_{\\text{eff}}$ 被元数据拖回高位。更麻烦的是算子侧：逐通道缩放要求矩阵乘在内层循环里按通道取缩放、做一次乘加，破坏了张量核心对连续块的吞吐友好访问，反量化从“一次标量广播”变成“逐元素索引”，指令开销与寄存器压力都上去了。逐元素缩放则几乎不可行——元数据与元素同量级，压缩收益归零。</p>\n<p>真实在线服务里这条路的代价是可测的：元数据要跟着权重一起从 HBM 读出，带宽节省被抵消一部分；缩放因子的读取模式若与元素不连续，还会引入额外的访存事务。工程上于是出现一个尴尬的中间地带——粒度细到能救精度，却细到付不起元数据与算子复杂度。论文要填的正是这个空档。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-4\">四 · 为什么非改不可：三个约束同时收紧</h3>\n<p>把痛点归拢，是三条约束在同时收紧。其一是显存容量：多卡节点上权重、KV 缓存、激活共享同一池显存，FP16 权重把可用空间压到很窄，批大小上不去，吞吐被并发度限制。其二是带宽：单步权重读取与 KV 读写争夺 HBM 带宽，$b_{\\text{eff}}$ 每降一档，读取时间近似线性下降，这是延迟与吞吐最直接的杠杆。其三是数值稳定性：扩散与注意力的激活分布随步数、随请求长度漂移，任何固定粒度的缩放都会在某些区间失配，误差在多层与多步中累积。</p>\n<p>这三条约束的交叉点要求一种格式：统计粒度比整张量细、元数据比逐通道省、算子实现能落进张量核心的块访问模式。用一句话定位——需要块粒度的缩放，让每块自己适配动态范围，而块大小把元数据比例控制在可接受范围。这就是 Microscaling 的切入点，块大小 $B$ 与元素位宽 $b_{\\text{elem}}$ 共同决定 $b_{\\text{eff}}$：</p>\n<div class=\"formula\">$$b_{\\text{eff}}=b_{\\text{elem}}+\\frac{b_{s}}{B}$$</div>\n<p>其中 $b_s$ 是缩放因子编码位宽（E8M0 为 8 位）。块越大，元数据越省但块内离群值影响越大；块越小，动态范围适配越准但元数据税越重。这个权衡是格式设计的核心，也是后续硬件块缩放支持的语义基础。</p>\n<p>举一个具体例子：某层权重矩阵按 32 元素一块切分，块内最大值推导缩放并以 E8M0 编码，元素存 FP4。此时 $b_{\\text{eff}}=4+8/32=4.25$，相比 FP16 的 16，权重读取时间在带宽受限下近似降到四分之一强；若改成 per-tensor FP8，$b_{\\text{eff}}\\approx 8$ 但精度被离群值拖累；若改成 per-channel FP4，元数据占比在小 $K$ 层上反超元素本身。块缩放是三者之间唯一同时满足带宽、精度与算子可实现性的点。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-5\">五 · 旧栈的算子耦合：格式一变，整条链路都要动</h3>\n<p>旧方案的另一层痛点在耦合。per-tensor 缩放的语义简单到可以塞进 kernel 的一个标量参数，per-channel 则需要算子感知通道布局。推理栈里权重与激活分别量化，矩阵乘、注意力 QK 与 PV 乘、归一化等逐元素算子各自持有自己的缩放约定；一旦格式从整张量换成块，反量化的位置与时机必须重排——是在读入时反量化成高精度再乘，还是在张量核心内融合缩放直接累加，决定了寄存器压力、流水线深度与数值误差的累积路径。</p>\n<p>工程代价体现在两处。其一是 kernel 变体爆炸：不同块大小、不同元素位宽、不同缩放编码组合，各自需要一套加载与反量化路径，编译与调优成本随组合数上升。其二是数值一致性：缩放因子编码与舍入语义若在权重侧与激活侧不一致，反量化误差会在多层串联中放大，表现为端到端精度漂移而非单层可定位的故障。论文把格式层、量化层、算子层的语义写清楚，正是为了让这条链路有统一的契约——块大小、元素位宽、缩放编码三者一旦固定，量化与反量化的行为就可复现，算子实现才有收敛的基准。</p>\n<p>回到开场的在线服务：在格式语义未标准化之前，每接一个新模型、每换一个 kernel 后端，量化配置都要重新对齐，服务化团队被迫在精度回退与吞吐回退之间反复试探。块缩放格式把这件事从“逐案调参”变成“按格式契约实现”，这是它进入推理栈的真正门槛所在，也是后续 NVFP4 类硬件路径能承接它的前提。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-6\">六 · 落点：块大小是第一个要定的工程参数</h3>\n<p>把旧方案的失败模式收束成一句可执行的判断：整张量缩放败在统计粒度，逐通道缩放败在元数据税与算子耦合，两者之间的空档由块粒度填补，而块大小 $B$ 是第一个必须定的工程参数。它同时决定三件事——元数据比例 $b_s/B$、块内离群值对共享缩放的拉高程度、以及算子按块读取缩放时的访存连续性。$B$ 取大，$b_{\\text{eff}}$ 低、带宽收益明显，但块内离群值压缩其余元素有效尾数；$B$ 取小，动态范围适配准，但元数据与索引开销回升。这个权衡没有普适最优，只能按层的统计特性与带宽预算逐层定，而格式定义必须先把这个自由度固定下来，量化与反量化语义才能跨算子一致。推理栈在块缩放上的第一道工程决策，不是选 FP4 还是 FP6，而是先确认块边界与缩放编码在权重侧和激活侧是否对齐——对齐了，后面的融合反量化与张量核心路径才有意义。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-7\">七 · 块缩放语义落地时的边界与代价</h3>\n<p>在一个多租户在线推理服务里，权重与激活的位宽决策从来不是“选个格式”这么简单：整张量共享一个缩放因子时，某条请求里一个离群激活就能把整层动态范围拉偏，其余元素的有效尾数被压扁；改成逐元素缩放，元数据又随元素数线性膨胀，显存与带宽被缩放因子本身吃掉。MX 的折中是固定块大小 B 内共享一个缩放 <span class=\"formula\">$$s=\\frac{\\max_{j\\in B}|x_j|}{q_{\\max}}$$</span>，元数据比例约为 <span class=\"formula\">$$r_{\\text{meta}}\\approx \\frac{b_s}{B\\cdot b_e}$$</span>（<span class=\"formula\">$$b_s$$</span> 为缩放编码位宽、<span class=\"formula\">$$b_e$$</span> 为元素位宽）。块越小，动态范围适配越细，但缩放因子的读取与反量化开销越高；块越大，元数据越省，离群值污染整块的风险越大。</p>\n<p>失效条件集中在“块内统计被单点主导”。若一个 32 元素块里出现一个幅值远超同块其余元素的激活，按最大值推导的 s 会把其余元素推到极低位深可表示的少数几个码点上，尾数精度骤降；这种损失不会在格式层报错，只在多层累加后表现为注意力 logits 偏移或归一化输出漂移。另一个失效点是缩放编码与算子实现不一致：E8M0 指数编码只保留 2 的幂次缩放，舍入语义若与张量核心内的融合反量化不匹配，误差会沿 QK、PV 乘逐层累积，且难以从端到端指标里定位。</p>\n<p>系统代价要按链路算。显存侧，权重按块量化后占用下降，但每个块附带缩放因子，块大小直接决定净收益；带宽侧，矩阵乘需按块读取缩放并在算子内融合反量化，若融合不彻底，缩放因子的额外读取会侵蚀低位宽带来的带宽节省。以一个图像生成推理的权重矩阵为例：按块切分、逐块取最大值推导 s、块内元素舍入为 FP4 并以 E8M0 编码缩放，推理时张量核心按块反量化累加；同一语义延伸到激活侧与注意力 QK／PV 乘，输出再按块量化写回供低精度存储。这条链路能否兑现收益，取决于块大小与位宽组合是否与显存带宽预算匹配——材料未给出端到端吞吐与精度对比数字，因此格式定义本身不能直接等同于服务化吞吐收益，工程判断应落在块粒度、缩放编码与算子融合一致性这三处可验证的约束上。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-8\">八 · 负载形态决定块缩放格式的收益边界</h3>\n<p>MX 格式的收益不是无条件成立的，它被推理负载的形态直接调制。块级共享缩放的核心代价结构是：每块携带一个缩放因子，元数据比例约为 <span class=\"inline-math\">1/(块元素数)</span>，而块内动态范围适配能力取决于块内元素的统计分布。当负载的激活张量呈现长尾分布——少数通道幅值远高于其余通道——块内离群值会把共享缩放因子拉高，同块其余元素的有效尾数位被压缩。这意味着 MXFP4 在某一层上的实际精度损失，不是由格式本身决定的常数，而是由该层激活在该批请求上的分布决定的随机量。请求长度分布越宽、并发越高，激活统计越接近全局分布，块内离群值出现的概率越高；反之，短请求、低并发下激活分布更集中，块缩放更接近理想工作点。</p>\n<p>测量口径上，必须区分“格式定义精度”与“负载相关精度”。可核查的做法是：对每一层记录块内最大值与块内次大值的比值分布（离群度指标），以及该层输出相对高精度基线的逐块相对误差。前者刻画负载形态，后者刻画格式代价，两者联合才能判断某一请求形态下 MXFP4 是否可用。推理系统代价体现在显存带宽：块缩放把权重与激活的存储压缩到 FP4，但每块附带的 E8M0 缩放因子使有效位宽上升，实际带宽节省小于名义位宽比；块越小，元数据开销越大，带宽收益越被侵蚀。</p>\n<p>具体例子：一个图像生成推理链路中，注意力 QK 乘的激活在少数通道上出现尖峰，若块大小取 32，尖峰所在块共享缩放被抬高，同块其余 31 个元素的有效精度下降；把块大小缩到 16 可缩小污染范围，但元数据比例翻倍，显存带宽收益下降。这一权衡必须按负载实测，不能从格式定义直接外推。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-9\">九 · 输入长度分布与批大小如何塑造量化粒度选择</h3>\n<p>输入长度分布通过两个通道影响 MX 方案。第一，序列长度决定激活张量的形状，进而决定块在张量内的切分方式：若块沿通道维切分，则不同 token 位置共享同一组缩放因子的机会不同；若块沿 token 维切分，则长序列带来更多块、更多元数据。第二，长尾请求（极长输入）会拉高整批的激活动态范围，若批内按张量级统计缩放，长尾请求污染整批；MX 的块级缩放正是为缓解这一点，但块边界若跨越不同请求的 token，污染仍在块内发生。因此连续批处理下，块切分应尽量对齐单请求边界，避免跨请求共享缩放。</p>\n<p>批大小的影响体现在统计稳定性与元数据带宽的竞争。大批量使每层激活的块数增多，缩放因子的读取次数线性上升，缩放因子本身成为额外的显存读流量；小批量下块数少，但每块的统计更容易被单个离群 token 主导。可核查的测量口径：按批大小分桶记录每层缩放因子读取字节数与元素读取字节数之比，以及该批内块内离群度指标的方差。前者是系统代价，后者是精度风险，二者随批大小的变化曲线决定最优批大小区间。</p>\n<div class=\"formula\">$$\\text{元数据占比}=\\frac{N_{\\text{block}}\\cdot b_s}{N_{\\text{block}}\\cdot n\\cdot b_e+N_{\\text{block}}\\cdot b_s}=\\frac{b_s}{n\\cdot b_e+b_s}$$</div>\n<p>其中 <span class=\"inline-math\">n</span> 为块元素数，<span class=\"inline-math\">b_e</span> 为元素位宽，<span class=\"inline-math\">b_s</span> 为缩放因子位宽。该式说明块越小、元素位宽越低，元数据占比越高，带宽节省越被抵消。具体例子：MXFP4 在块大小 32、缩放因子 8 位时，元数据占比约 1/17；块大小降到 16 则约 1/9，带宽收益明显缩水。这一计算不依赖实测，可直接用于容量规划。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-10\">十 · SLO 与长尾：延迟预算如何反向约束格式选择</h3>\n<p>SLO 通过尾延迟约束反向限制 MX 方案的使用范围。块缩放算子在矩阵乘中需要按块读取缩放并融合反量化，这一融合若在张量核心内完成，延迟与纯低精度乘加接近；若需先反量化到寄存器再乘，则引入额外指令与寄存器压力，尾延迟上升。长尾请求（超长输入、超大 batch 中的个别请求）会放大这一代价：其激活块数多，缩放因子读取与反量化步骤在关键路径上累积。可核查的测量口径是按请求长度分桶记录 P99 延迟与每 token 的缩放因子读取次数，观察尾延迟是否随块数超线性增长。</p>\n<p>反过来，SLO 也塑造负载：为守住尾延迟，调度器会限制单批 token 总数、拆分长请求、或对长请求降级到更高位宽格式。这些调度决策改变了实际到达算子的批形态，进而改变块内统计分布——拆分长请求使单块内 token 更同质，离群污染降低；降级到 FP8 则放弃 MXFP4 的带宽收益。方案与负载在此形成闭环：格式的精度风险促使调度保守，保守调度又降低了格式的实际收益，容量规划必须把这一反馈计入。</p>\n<p>具体例子：某服务对 P99 延迟设硬约束，长请求被拆成固定长度片段分别批处理，每片段的激活块统计更集中，MXFP4 的块内离群度指标方差下降，格式可用性提高；代价是拆分带来额外的 KV 缓存读写与调度开销，这部分开销需与带宽节省做净额比较。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-11\">十一 · 可核查的测量口径清单</h3>\n<p>要让“负载塑造方案”这一判断可复核，需固定一组测量口径，避免用格式定义直接替代端到端结论。以下口径均可在服务侧埋点采集，不依赖论文未给出的数字。</p>\n<ul>\n<li>输入长度分布：按 token 数分桶的请求计数与占比，记录 P50/P99 长度；用于判断块切分是否需对齐请求边界。</li>\n<li>并发与批形态：实际到达算子的批内 token 总数、批内请求数、跨请求块占比；用于评估跨请求缩放污染。</li>\n<li>块内离群度：每层每块的最大值与次大值比值分布，及其随批大小的方差；用于量化精度风险。</li>\n<li>元数据带宽比：缩放因子读取字节与元素读取字节之比，按层、按批大小分桶；用于核算真实带宽节省。</li>\n<li>尾延迟分解：P99 延迟中缩放读取、反量化、矩阵乘各段占比，按请求长度分桶；用于判断融合反量化是否在关键路径。</li>\n<li>降级触发率：因 SLO 压力切换到更高位宽格式的请求比例；用于评估方案实际收益被调度侵蚀的程度。</li>\n</ul>\n<p>这些口径的共同点是：把格式的静态属性（块大小、位宽、缩放编码）与负载的动态属性（长度、并发、离群度）分开记录，再联合分析。缺少任一侧，结论都不可核查。推理系统代价在此体现为显存带宽与尾延迟的联合预算：带宽节省若以尾延迟上升为代价，需按 SLO 约束折算为可接受的净收益。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-12\">十二 · 方案反向限制负载的工程判断</h3>\n<p>MX 方案一旦选定块大小与位宽，就会反向限制可服务的负载形态。块大小固定后，跨请求共享缩放的概率由调度器的批组装策略决定；若调度器按到达顺序组批，不同长度请求混在同一块内，离群污染概率上升，格式的实际精度边界收窄。工程上可做的判断是：把块边界与请求边界对齐作为调度约束，代价是批组装灵活性下降、批利用率可能降低，这部分吞吐损失需与精度收益做净额比较。另一个反向限制是缩放因子编码：E8M0 指数编码的动态范围宽但尾数精度为零，若负载激活的块内分布跨多个数量级，指数编码的量化台阶会引入系统性偏差，需在算子侧验证反量化误差是否随层数累积。</p>\n<p>具体机制上，注意力 QK 与 PV 乘沿用块缩放语义，意味着 KV 缓存也需按块存储缩放因子；KV 缓存随请求长度线性增长，缩放因子的额外显存占用随长度线性上升，长尾请求的显存代价被放大。可核查的测量口径是 KV 缓存中缩放因子字节占比随序列长度的变化曲线。工程判断落在：块大小选择需同时满足带宽预算、精度风险预算与 KV 缓存显存预算三者，任一预算紧张都会反向压缩可服务的负载形态，容量规划应把这一压缩显式建模，而非假设格式收益与负载无关。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-13\">十三 · 块缩放格式在请求形态下的边界：元数据比例、离群块与 SLO 长尾</h3>\n<p>MX 格式的元数据开销由块大小直接决定，这是负载塑造方案的第一条硬约束。设块大小为 <span class=\"inline-math\">B</span>、元素位宽为 <span class=\"inline-math\">b</span>、缩放因子位宽为 <span class=\"inline-math\">e</span>，则有效位宽为 <span class=\"inline-math\">b + e/B</span>。以 MXFP4 配 E8M0 为例，块内 32 个元素共享 8 位指数，元数据摊薄到每元素 0.25 位，有效位宽约 4.25 位；若块缩小到 16，元数据升至 0.5 位，显存与带宽收益立刻被吃掉一截。推理系统的代价因此是可算的：权重常驻显存按有效位宽线性缩放，而解码阶段的每 token 带宽需求近似正比于“权重有效位宽 + KV 有效位宽”，块越小、并发越高，带宽压力越早顶到 HBM 天花板。这也是为什么块大小不能由精度单方面决定——它同时是显存预算、带宽预算与算子融合粒度的三方交点。</p>\n<p>请求形态对这套格式的第二个塑造点是离群值在块内的分布，而它与输入长度分布强耦合。长输入、长上下文请求会让激活张量的动态范围在序列维度上剧烈波动：某些 token 的激活幅值远高于同块其余元素，按 <span class=\"inline-math\">s = max|x_j| / q_max</span> 推导出的共享缩放被这一个元素拉高，同块其余元素的有效尾数位被压缩。失效条件是明确的：当块内极值比（max/median）超过该位宽可承受的动态范围，量化误差不再由舍入噪声主导，而由缩放失配主导，并且这种误差会在 QK、PV 乘与逐元素算子中逐层累积。工程上的应对不是缩小块（元数据代价），而是按张量角色分块：权重侧分布稳定可用较大块，激活侧在注意力链路沿用块缩放语义时需与算子实现严格对齐舍入语义，否则反量化误差在多层叠加后无法归因。</p>\n<p>负载与方案的相互限制最终落在 SLO 的长尾上。批大小与并发由 TTFT/TPOT 目标反推，而低位宽格式改变的是单步成本曲线而非请求到达分布：它压低每 token 的权重带宽，却让长尾请求（超长预填、罕见离群激活）的方差更突出。可核查的测量口径应至少包含三项：按块统计的极值比分布（而非全局最大值），用于判断离群块比例；有效位宽与实际 HBM 读写字节数之比，用于验证元数据是否被算子真正摊薄；以及分位延迟（P50/P99）下每 token 的带宽占用，用于区分“格式收益”与“调度收益”。材料未给出端到端吞吐与精度对比数字，因此任何把格式定义直接等同于服务化吞吐提升的判断都不成立——块大小与位宽组合的精度损失边界尚未量化，这正是容量规划时必须留出的不确定区间。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>口径</th><th>失效信号</th></tr></thead><tbody><tr><td>离群块比例</td><td>块内 max/median 超阈值计数</td><td>缩放失配主导误差</td></tr><tr><td>元数据摊薄率</td><td>实际读写字节 / 理论元素字节</td><td>算子未融合缩放</td></tr><tr><td>长尾带宽</td><td>P99 请求每 token HBM 字节</td><td>长上下文预填挤占解码</td></tr></tbody></table>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-14\">十四 · 从格式语义到算子契约：块缩放如何进入矩阵乘</h3>\n<p>MX 格式的定义只解决“数怎么存”，真正决定推理速度与数值稳定的是“算子怎么读”。在 MXFP4/MXFP6/MXFP8 中，一个块 B 共享缩放因子 s，块内元素 q_i 为低精度整数或浮点。算子层必须在矩阵乘的 K 维上按块对齐读取 s，并在累加前完成反量化。对 GEMM 而言，这意味着 K 维不再是连续的低精度字节流，而是“缩放因子 + 元素块”的交错布局；对注意力而言，QK 与 PV 两个乘法的 K 维分别对应头维与序列维，块边界必须与头维长度或分块 tile 对齐，否则缩放因子会被跨块错误复用。</p>\n<p>把论文公式逐项展开：</p>\n<div class=\"formula\">$$x_i = s \\cdot q_i,\\quad s = \\frac{\\max_{j\\in B}|x_j|}{q_{\\max}},\\quad q_i=\\mathrm{round}\\left(\\frac{x_i}{s}\\right)$$</div>\n<p>第一项 x_i = s·q_i 是反量化恒等式，它要求算子在同一时刻持有 s 与 q_i；第二项 s 由块内绝对值最大值除以该位宽可表示的最大量化值 q_max 得到，q_max 对 FP4 是尾数加指数的可表示上界，对 E8M0 编码的 s 则是 2 的幂次格点；第三项 q_i 是就近取整。三项合起来决定了误差结构：s 被块内最大值“钉死”，块内小元素除以大 s 后落入低位尾数，尾数位被浪费；q_i 的舍入误差再乘以 s 回到原尺度，因此误差上界与 s 成正比，而 s 又正比于块内最大值。这就是块内离群值拉高共享缩放、压缩其余元素有效精度的数学来源。</p>\n<p>工程代价落在三处。其一是元数据带宽：块越小，s 越多，读取 q 的同时还要读 s，有效带宽被元数据稀释；块越大，离群值污染越广。其二是反量化指令开销：若在 CUDA core 上逐元素乘 s，FP4 的算力优势会被标量乘法吃掉；因此 Blackwell 路径要求把缩放融合进张量核心的块缩放通路。其三是累加器位宽：q_i 是低精度，但块内乘积之和必须在 FP32 累加器中完成，否则多层链路的舍入误差会累积。一个具体例子：一个 K=4096 的权重矩阵按 32 元素块切分，得到 128 个缩放因子；若每个因子以 E8M0 单字节编码，元数据为 128 字节，相对 FP4 主体 2048 字节的占比约百分之六，这就是块大小换来的固定开销。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-15\">十五 · 数据类型谱系：FP16/BF16/FP8/NVFP4 各自承担什么</h3>\n<p>推理链路上不同张量对动态范围与尾数精度的需求并不相同，格式选择应按“谁最怕离群值”来分配。FP16 尾数多、范围窄，适合对精度敏感但数值分布温和的路径；BF16 用指数位换尾数位，范围与 FP32 对齐，适合激活中偶发大幅值的场景；FP8 分 E4M3 与 E5M2 两支，E4M3 尾数多适合权重与激活的主体，E5M2 范围大适合梯度类或极端值；NVFP4 则在 FP4 元素之上叠加块级缩放，用缩放因子补回 FP4 仅有的一位尾数所丢失的动态范围。</p>\n<p>关键判断是：MXFP4 与 NVFP4 的差别不在元素位宽，而在缩放因子的编码与块粒度语义。MX 用 E8M0 指数编码 s，s 只能取 2 的幂，量化步长随块最大值跳变；NVFP4 类路径在硬件中把块缩放与元素打包成张量核心可直接消费的布局。对算子作者而言，这意味着同一份权重在 MXFP4 与 NVFP4 下的反量化代码不能互换：前者需要把 E8M0 解码为 2 的幂再乘，后者依赖硬件块缩放单元在 MMA 内部完成。若框架把两者混用，反量化误差会在层间累积。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>尾数/指数取向</th><th>算子侧主要代价</th><th>典型放置</th></tr></thead><tbody><tr><td>FP16</td><td>尾数优先</td><td>带宽翻倍于 FP8，累加仍需 FP32</td><td>精度敏感的小矩阵或残差</td></tr><tr><td>BF16</td><td>指数优先</td><td>尾数少，块内小元素误差放大</td><td>激活主体、归一化输出</td></tr><tr><td>FP8 E4M3</td><td>平衡</td><td>需 per-tensor 或 per-block 缩放防饱和</td><td>权重与激活的 GEMM 输入</td></tr><tr><td>MXFP4/NVFP4</td><td>块缩放补范围</td><td>元数据读取与块对齐约束</td><td>带宽受限的大权重矩阵</td></tr></tbody></table>\n<p>一个具体例子：注意力中 QK 乘的 K 维是头维，若头维为 128 且块大小为 32，则每个头恰好四个块，缩放因子可按头对齐存放；若块大小为 16，则八个块，元数据翻倍但离群值污染减半。这个取舍直接改变注意力的有效带宽与数值误差，而不是格式定义本身能回答的。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-16\">十六 · 累加精度与误差传播：FP32 累加器不是可选项</h3>\n<p>低精度乘低精度得到的是低精度乘积，但块内求和必须在高精度累加器里完成。原因在于：q_i 的舍入误差经 s 放大后是绝对误差，若在 FP16 累加器中求和，K 维较长时部分和会触及 FP16 的尾数上限，后续小项被吞掉。MX 论文的语义要求反量化后按块累加，工程实现上对应张量核心的 FP32 累加通路；Blackwell 的第五代 Tensor Core 在 MMA 指令中保留 FP32 累加器，使 FP4 输入不必中途降精度。</p>\n<p>误差传播可按层估算：设单块反量化相对误差为 ε_b，它由 q_i 的舍入步长与 s 共同决定；一层 GEMM 的输出误差近似为各块误差按权重绝对值加权的和。若块内存在一个远大于其余元素的离群值，s 被抬高，其余元素的 ε_b 随之变大，该块的贡献在加权和中被放大。这就是“块内离群值仍会拉高共享缩放”的算子级后果，也是块大小不能无限放大的原因。</p>\n<div class=\"formula\">$$\\hat{y}=\\sum_{b}\\sum_{i\\in b} s_b\\,\\hat{q}_i w_i,\\qquad \\varepsilon_b \\propto \\frac{s_b}{2^{m}}$$</div>\n<p>其中 m 为元素尾数位数，s_b 为该块缩放。公式说明：误差与 s_b 成正比、与尾数位成反比，因此降低 s_b 的唯一办法是缩小块或改用统计方式（如去掉块内最大值后再定 s），而提高 m 则直接增加位宽与带宽。一个具体例子：同一权重矩阵，块大小 32 时某块最大值是其余元素的数十倍，s 被抬高后其余元素只剩一两位有效尾数；把块缩小到 16 后该离群值单独成块，其余块的 s 回落，整体误差下降，但元数据比例上升。这是精度与带宽的直接兑换，材料未给出定量边界，工程上只能按层做敏感性分析。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与块缩放的咬合</h3>\n<p>Blackwell 的 tcgen05 指令族把张量核心的输入输出搬到了 TMEM（Tensor Memory）上，累加器与操作数不再全部挤在寄存器文件里。对块缩放格式而言，这带来两个直接后果：其一，缩放因子可以作为 MMA 的附带操作数随元素块一起进入张量核心，反量化在数据通路内完成，不必先写回寄存器再乘；其二，TMEM 的容量决定了单次 MMA 能容纳的累加器 tile 大小，进而决定 K 维分块与缩放因子读取的节奏。</p>\n<p>2-SM MMA 让两个 SM 协同执行一个更大的 MMA tile，等效于把单个 MMA 的 M 或 N 维翻倍。对 MXFP4 这类低精度格式，算力相对带宽更富裕，瓶颈从 MMA 吞吐转向权重与缩放因子的读取；2-SM 协作减少的是指令发射与同步开销，而不是带宽。因此算子设计要把块对齐到 2-SM tile 的边界，使两个 SM 各自读取的缩放因子不跨界、不重复。第五代 Tensor Core 的块缩放支持是格式语义落地的硬件前提：没有它，MXFP4 的反量化只能退回 CUDA core，算力收益被标量乘法抵消。</p>\n<p>代价方面：TMEM 容量限制了同时在飞的累加器数量，连续批处理下若 batch 维切得太碎，TMEM 利用率下降；2-SM MMA 要求两个 SM 的 tile 形状一致，负载不均时一个 SM 空转，吞吐按最慢者计。一个具体例子：一个 N 维较大的权重矩阵在 2-SM MMA 下按 N 切分给两个 SM，若块大小 32 且 N 切分边界不在块边界上，则边界处的缩放因子被两个 SM 各读一次，元数据带宽翻倍且反量化语义需保证一致。这是格式层与算子层必须共同约束的边界条件。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-18\">十八 · 算子实现中的三个具体咬合点</h3>\n<p>第一个咬合点是权重布局。MX 格式要求缩放因子与元素块在内存中按固定 stride 交错，若框架沿用传统的行主序权重布局，算子需在加载时做重排，重排本身消耗带宽。工程判断是：在模型转换阶段就把权重写成块对齐布局，让推理时的加载是连续的，而不是在 kernel 内做 gather。</p>\n<p>第二个咬合点是激活的在线量化。激活在推理时动态产生，块统计必须在线完成：先读块内最大值，再定 s，再舍入。这引入一次额外的块内归约，代价是延迟；若把归约与后续 GEMM 融合，则需保证归约结果在 MMA 启动前可见。一个具体例子：注意力中 PV 乘的激活块若在 softmax 之后才量化，softmax 输出的动态范围已被压缩，s 更稳定；若在 softmax 之前量化，离群值会污染 s，QK 与 PV 的误差不对称。</p>\n<p>第三个咬合点是 KV 缓存。KV 以低精度存储时，块缩放语义要沿序列维一致：同一头的 K 与 V 若按不同块大小量化，反量化后的点积误差不可比。工程上通常让 K 与 V 共用块大小与缩放编码，输出按块重新量化写回，供下一层以低精度读取。代价是 KV 缓存的元数据占用随块大小反比变化，块越小，缓存中缩放因子的字节数越多，显存带宽预算需把这块算进去。</p>\n<ul><li>权重：转换期重排为块对齐布局，推理期连续加载，避免 kernel 内 gather。</li><li>激活：在线块统计与 GEMM 融合，归约结果必须在 MMA 前可见。</li><li>KV：K/V 共用块大小与缩放编码，输出按块重量化写回。</li></ul>\n<p>这三个咬合点共同决定一件事：MX 格式的数值语义只有在算子按块读取缩放、按块反量化、按 FP32 累加时才成立。格式定义给出的是契约，算子实现决定契约是否被遵守；任何一处 stride 或块边界错位，都会让反量化误差在多层链路中累积，而这类误差不会在单层测试中暴露。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-19\">十九 · 块缩放语义在算子边界上的失效条件与系统代价</h3>\n<p>MX 格式的算子契约是“按块读缩放、块内融合反量化”，其正确性依赖一个隐含前提：同一块内元素的动态范围被共享缩放因子充分覆盖。失效点正在这里——若块内出现一个幅值远超其余元素的离群值，缩放因子被该值拉高，同块其余元素的有效尾数位被压缩。以块大小 32、元素 FP4 为例，FP4 仅 1 位符号、2 位指数、1 位尾数，可表示值域极窄；一旦缩放因子由块内最大值决定，其余元素落入更低的指数区间，尾数有效位进一步减少，反量化后的相对误差在多层累加中放大。块大小是这一失效面的直接旋钮：块越小，统计粒度越细、离群值污染范围越小，但元数据比例上升；块越大，元数据开销下降，离群值污染面扩大。元数据比例可写为</p>\n<div class=\"formula\">$$r_{\\text{meta}}=\\frac{b_s}{b_s\\cdot b_e+b_s}=\\frac{1}{b_e+1}$$</div>\n<p>其中 $b_s$ 为块内元素数、$b_e$ 为元素位宽；缩放因子以 E8M0 编码时占 8 位。该式说明元数据占比只由元素位宽决定、与块大小无关，而块大小只改变统计粒度与污染面——这纠正了“块越大越省”的直觉：省的是缩放因子的绝对条数，不是比例。</p>\n<p>第二个边界在缩放因子的编码与舍入语义。E8M0 只存指数、不存尾数，缩放因子被强制到 2 的幂，量化式 $q_i=\\mathrm{round}(x_i/s)$ 中的 $s$ 因此只能取离散幂次，块内最大值与 $s\\cdot q_{\\max}$ 之间存在固有间隙，这部分间隙直接表现为块内最大元素的截断误差。若算子实现用 FP8 指数而非 E8M0 编码缩放，反量化路径必须与量化路径严格一致，否则缩放语义错位会在 QK、PV 与逐元素归一化之间逐层累积，且这种误差不随批大小摊薄。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>块内离群值</td><td>共享缩放被最大值拉高，其余元素尾数被压缩</td><td>精度损失，需缩小块或改统计方式，元数据条数上升</td></tr><tr><td>E8M0 幂次缩放</td><td>缩放只能取 2 的幂，块内最大值存在截断间隙</td><td>块内最大元素系统性偏低，多层累加偏差</td></tr><tr><td>算子缩放语义不一致</td><td>量化与反量化路径编码不同</td><td>误差跨层累积，注意力链路难定位</td></tr></tbody></table>\n<p>第三个代价在算子融合形态。按块反量化意味着矩阵乘内核必须在每次 MMA 前读取缩放因子并做块内乘法，这部分工作若不能并入张量核心的块缩放通路，就会以额外指令与寄存器压力形式占用 SM 周期；在注意力中，QK 与 PV 乘沿用块缩放语义，缩放因子的读取与 K/V 缓存布局耦合，若 KV 以低精度块存储，反量化必须与缓存读取同拍完成，否则带宽节省被反量化开销抵消。工程判断是：块大小与元素位宽的组合必须与内核的块缩放支持粒度对齐，缩放编码在量化、算子、缓存三处保持同一语义，离群值块则需在统计方式上单独处理，而不是靠调大块来摊薄元数据。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-20\">二十 · 显存账本的三本分册：权重、激活、KV</h3>\n<p>在 Blackwell 上做推理容量规划，第一件事不是问“能塞多少参数”，而是把显存拆成三本互不挪用的账：权重（静态、只读、随模型走）、激活（动态、随批与序列长度走、峰值出现在特定算子）、KV cache（半静态、随并发与上下文长度线性增长、可回收可复用）。MX 格式族的块缩放语义直接改写了这三本账的记账单位——不再是“每元素多少字节”，而是“每块多少元素 + 每块一份缩放元数据”。设块大小为 <span class=\"inline-math\">B</span>，元素位宽为 <span class=\"inline-math\">b</span>，缩放因子编码为 <span class=\"inline-math\">e</span> 位，则单块有效位宽为</p>\n<div class=\"formula\">$$b_{\\text{eff}} = b + \\frac{e}{B}$$</div>\n<p>这个式子是全篇的锚点。MXFP4 在 <span class=\"inline-math\">B=32</span>、<span class=\"inline-math\">e=8</span>（E8M0 指数）时，<span class=\"inline-math\">\\(b_{\\text{eff}}=4.25\\)</span> 位/元素；若把块缩到 <span class=\"inline-math\">B=16</span>，元数据占比翻倍到 4.5 位；若放大到 <span class=\"inline-math\">B=64</span>，降到 4.125 位但块内离群值污染面扩大。这不是纯算术问题：块越小，统计粒度越细、离群值拉高共享缩放的概率越低，但元数据带宽与解码指令开销上升；块越大则相反。工程判断落在“元数据占比是否被 HBM 带宽吞掉”这一条线上。</p>\n<p>三本账的记账方式不同。权重按块量化后是纯静态字节数，一次读入可反复用，其显存占用等于参数量乘 <span class=\"inline-math\">\\(b_{\\text{eff}}/8\\)</span>；激活的峰值不在存储而在带宽——每层都要重写重读，块缩放让激活的读写字节数同比下降，但反量化指令与缩放因子读取引入额外访存；KV cache 最特殊，它是唯一随服务负载增长的账，且历史 token 的 K/V 一旦写入就长期驻留，量化误差会在整个上下文生命周期内累积。</p>\n<p>具体例子：一个 70B 级稠密模型，权重按 MXFP8（<span class=\"inline-math\">B=32</span>，<span class=\"inline-math\">e=8</span>，<span class=\"inline-math\">\\(b_{\\text{eff}}=8.25\\)</span>）存储，权重账约为参数量的 1.03 倍字节数；若改 MXFP4，权重账压到约一半，但激活侧若仍走 FP8，则权重与激活的位宽不再对齐，算子需在矩阵乘内做混合位宽反量化，代价是张量核心流水线里多一级缩放乘法。这正是块缩放格式“权重激进、激活保守”的典型部署形态。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-21\">二十一 · 分页与块对齐：页大小必须被块大小整除</h3>\n<p>KV cache 的分页（paged attention 类机制）把逻辑序列切成固定 token 数的页，物理页按需分配。MX 块缩放给分页加了一条硬约束：一个量化块不能跨页，否则反量化时缩放因子要跨页读取，破坏页内局部性。因此页内 token 数乘以每 token 的 KV 头维度必须能被块大小整除。设页含 <span class=\"inline-math\">T</span> 个 token、每 token 每头 KV 维度为 <span class=\"inline-math\">d</span>，则要求</p>\n<div class=\"formula\">$$\\frac{T \\cdot d}{B} \\in \\mathbb{Z}^{+}$$</div>\n<p>实际部署里 <span class=\"inline-math\">d</span> 常为 128 或 64，<span class=\"inline-math\">B=32</span> 时该条件几乎自动满足；但若采用 <span class=\"inline-math\">B=16</span> 的细粒度块以压制离群值，则 <span class=\"inline-math\">\\(T \\cdot d\\)</span> 必须是 16 的倍数，页大小选择空间收窄。代价是显存碎片：页越大，尾部浪费越多；页越小，页表元数据与页管理开销越大。一个 128 token 的页在 <span class=\"inline-math\">d=128</span>、单头 FP8 KV 下是 32KB 量级，块对齐后每页恰好含整数个 MX 块，反量化可在页内一次完成，缩放因子随页元数据一起驻留。</p>\n<p>分页的另一个收益是复用：前缀共享、系统提示、多轮对话的历史段可以指向同一物理页，KV 的块缩放因子也随之共享，不需要为每个请求重复量化。这在连续批处理下把 KV 的“写”成本摊薄，但“读”成本不变——每个解码步仍要把整个上下文对应的 KV 页读一遍，带宽瓶颈就落在这里。</p>\n<p>具体例子：并发 64、平均上下文 8K token、每 token KV 按 MXFP8 存储的模型，KV 账随并发线性放大；若把页大小从 128 调到 256，页表项减半、碎片略增，但块对齐条件更宽松。工程上应优先保证块对齐，再在碎片与页表开销之间调页大小。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-22\">二十二 · 带宽瓶颈的定位：解码步是 KV 读带宽的函数</h3>\n<p>自回归解码每步只算一个 token，算力远未饱和，时间几乎完全由“把权重和 KV 从 HBM 搬到 SM”决定。设每步需读的权重字节为 <span class=\"inline-math\">W</span>、KV 字节为 <span class=\"inline-math\">K</span>、HBM 有效带宽为 <span class=\"inline-math\">BW</span>，则单步下界为</p>\n<div class=\"formula\">$$t_{\\text{step}} \\gtrsim \\frac{W + K}{BW}$$</div>\n<p>MX 格式对两项的作用不对称：<span class=\"inline-math\">W</span> 随 <span class=\"inline-math\">\\(b_{\\text{eff}}\\)</span> 同比下降，收益直接；<span class=\"inline-math\">K</span> 的下降被缩放因子读取部分抵消——每个 KV 块要多读一份指数，且反量化在 SM 内做乘法，若缩放因子未与数据同页驻留，会引入额外的小粒度随机访存，反而拖低有效带宽。这就是“压缩了字节数却没等比例缩短步时”的典型现场。</p>\n<p>预填充阶段则相反：算力主导，矩阵乘的算术强度高，块缩放的收益体现在张量核心吞吐而非带宽。分离式预填/解码把这两种形态拆到不同资源池，KV 的量化格式必须在两侧一致，否则跨池传输要做格式转换，NIXL 之类的传输层要按块搬运缩放因子与元素，元数据成为传输开销的一部分。</p>\n<p>具体例子：解码步读权重 <span class=\"inline-math\">W</span> 与上下文 KV <span class=\"inline-math\">K</span>，当上下文很长时 <span class=\"inline-math\">K</span> 超过 <span class=\"inline-math\">W</span>，KV 量化成为主导杠杆；当并发高、上下文短时 <span class=\"inline-math\">W</span> 主导，权重格式才是杠杆。容量规划必须按负载形态分别定权重与 KV 的位宽，而不是全链路一个格式。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-23\">二十三 · 压缩、复用与卸载：KV 的三级台阶</h3>\n<p>KV 的显存压力有三条缓解路径，代价各不相同。其一是压缩：按块量化把 KV 位宽从 FP16/BF16 降到 MXFP8 或 MXFP4，账本按 <span class=\"inline-math\">\\(b_{\\text{eff}}\\)</span> 缩，但历史 token 的量化误差不可逆，长上下文下误差随层数累积，需在块大小与统计方式上留余量。其二是复用：前缀缓存与页共享让相同前缀的 KV 只存一份，收益取决于负载的前缀重复率，对多轮对话与 RAG 场景显著，对开放域生成有限。其三是卸载：把冷 KV 页换到主机内存或远端存储，按需回迁，代价是 PCIe 或网络往返延迟，只适合长尾请求。</p>\n<p>三者可以叠加，但叠加顺序影响正确性：先量化再分页，块对齐约束在量化时就要满足；先分页再量化，则每页独立统计缩放因子，页边界处动态范围跳变，跨页注意力计算需处理两套缩放。工程上倾向“量化在写入时完成、分页在分配时完成”，让缩放因子成为页元数据的一部分。</p>\n<p>具体例子：多轮对话场景下，系统提示与前几轮历史构成稳定前缀，前缀缓存命中后 KV 复用率上升，此时 KV 账的实际增速低于线性；而每轮新增 token 仍需按块量化写入，写带宽成为新瓶颈。若把冷页卸载到主机内存，回迁延迟会打断解码步的流水，需用预取把回迁藏在计算之后。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-24\">二十四 · 可复算的显存预算：从位宽到 GB 的闭环</h3>\n<p>给出一套可手工复算的预算流程，全部输入为可观测参数，不依赖实测数字。第一步，按格式算有效位宽 <span class=\"inline-math\">\\(b_{\\text{eff}}\\)</span>；第二步，权重账 = 参数量 × <span class=\"inline-math\">\\(b_{\\text{eff}}/8\\)</span>；第三步，KV 账 = 并发 × 上下文长度 × 层数 × 每层 KV 头维度 × 2（K 与 V）× <span class=\"inline-math\">\\(b_{\\text{eff,KV}}/8\\)</span>，再乘上页对齐与碎片系数；第四步，激活账按峰值批的中间张量估算，取最大层的隐藏维度乘批大小乘 <span class=\"inline-math\">\\(b_{\\text{eff,act}}/8\\)</span> 再乘一个安全系数；第五步，加上框架与通信缓冲的固定开销。五项相加与单卡 HBM 容量比较，差额决定并行度与卸载策略。</p>\n<table class=\"mini\"><thead><tr><th>账本</th><th>记账单位</th><th>随什么增长</th><th>压缩杠杆</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × b_eff/8</td><td>模型规模（静态）</td><td>元素位宽、块大小</td></tr><tr><td>激活</td><td>批 × 隐藏维 × b_eff/8</td><td>批大小、序列长度</td><td>块缩放粒度</td></tr><tr><td>KV</td><td>并发 × 上下文 × 层 × 头维 × 2 × b_eff/8</td><td>并发与上下文（动态）</td><td>KV 位宽、分页复用、卸载</td></tr></tbody></table>\n<p>复算示例（仅演示方法，不引用实测）：设权重参数量为 <span class=\"inline-math\">P</span>，MXFP4 下权重账 ≈ <span class=\"inline-math\">P × 4.25/8</span> 字节；KV 按 MXFP8（<span class=\"inline-math\">\\(b_{\\text{eff}}=8.25\\)</span>）算，单 token 单层 KV 字节 = 头维 × 2 × 8.25/8；乘以层数与上下文得单请求 KV 账；再乘并发得总 KV 账。把权重账与 KV 账相加，若超过单卡容量，则要么降 KV 位宽、要么减并发、要么把权重切到多卡并用 NVLink 5 做张量并行——此时通信量随切分维度上升，需与带宽预算一起核算。</p>\n<p>预算的敏感性分析比绝对值更有用：KV 账对并发与上下文是双线性，任何一项翻倍都让 KV 账翻倍；权重账对块大小不敏感（<span class=\"inline-math\">B</span> 从 32 到 16 只让 <span class=\"inline-math\">\\(b_{\\text{eff}}\\)</span> 从 4.25 变 4.5），但对元素位宽高度敏感。因此容量规划的第一杠杆永远是 KV 的位宽与复用策略，第二杠杆才是权重格式。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-25\">二十五 · 块内离群值与账本误差：格式语义决定预算可信度</h3>\n<p>预算算得再细，若格式语义与算子实现不一致，账本就会失真。MX 的缩放因子由块内绝对值最大值推导，块内离群值会拉高共享缩放，压缩同块其余元素的有效尾数——这在账本上不体现为字节数变化，却体现为“同样的位宽、更差的数值质量”，逼得部署方要么缩小块、要么对离群通道单独处理，两者都改变预算。缩放因子编码为 E8M0 指数时只有幂次、没有尾数，反量化是纯指数缩放，硬件实现简单；若改用带尾数的 FP8 缩放，动态范围适配更细但解码多一次乘法。算子必须与格式定义严格对齐：块边界、缩放读取顺序、舍入模式任何一处不一致，误差都会在多层累积，最终表现为长上下文下 KV 复用页的数值漂移。</p>\n<p>因此显存预算应附带一条“语义校验”条款：确认框架的量化 kernel 与格式定义的块大小、缩放编码、舍入语义一致，确认 KV 写入与读取走同一套块缩放路径，确认跨页、跨池传输不做隐式重量化。做不到这三条，预算里的 <span class=\"inline-math\">\\(b_{\\text{eff}}\\)</span> 就只是纸面数字。工程判断落在：先锁定格式语义，再谈位宽选择；先保证块对齐与页对齐，再谈压缩率。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-26\">二十六 · 块缩放格式的显存账本：从格式语义到 KV 预算的边界条件</h3>\n<p>MX 格式对显存账本的影响不是“位宽除以二”这么简单，元数据比例由块大小决定：块越大，缩放因子开销越低，但块内离群值拉高共享缩放的概率越高；块越小，动态范围适配越细，但 E8M0 缩放因子本身要占带宽。设元素位宽为 <em>b</em>、块大小为 <em>k</em>、缩放因子位宽为 <em>e</em>，则有效每元素比特数为 <em>b</em> + <em>e</em>/<em>k</em>。以 MXFP4（<em>b</em>=4、<em>e</em>=8）为例，<em>k</em>=32 时有效位宽为 4.25 bit，相对 FP16 的权重静态占用约为 26.6%；若把 <em>k</em> 缩到 16，有效位宽升到 4.5 bit，元数据带宽占比从 5.9% 升到 11.1%。这条式子必须和 HBM3e 容量一起算：权重账本可写成 <em>M</em><sub>w</sub> = <em>N</em><sub>param</sub> × (<em>b</em> + <em>e</em>/<em>k</em>) / 8，KV 账本则是 <em>M</em><sub>kv</sub> = 2 × <em>L</em> × <em>H</em><sub>kv</sub> × <em>d</em> × <em>B</em> × <em>S</em> × (<em>b</em><sub>kv</sub> + <em>e</em>/<em>k</em>) / 8，其中 <em>L</em> 为层数、<em>H</em><sub>kv</sub> 为 KV 头数、<em>d</em> 为头维、<em>B</em> 为并发批、<em>S</em> 为上下文长度。工程上先算权重静态占用，再用剩余容量反推 <em>B</em>×<em>S</em> 的上限，而不是先定批再找显存。</p>\n<p>失效条件集中在三处。其一，块内离群值：缩放因子 <em>s</em> = max<sub>j∈B</sub>|<em>x</em><sub>j</sub>| / <em>q</em><sub>max</sub> 由块内最大值决定，一个离群元素会把同块其余元素的尾数精度压掉，MXFP4 在 <em>k</em>=32 时只有 3 位尾数量级，这种压缩不可忽略；缓解手段是缩小块、按通道重排或对离群通道做混合精度旁路，代价是元数据带宽上升或算子分支增多。其二，缩放因子编码与舍入语义必须与算子实现逐位一致，E8M0 指数编码在跨层累加时若与张量核心的融合缩放路径不一致，反量化误差会沿层累积，表现为长上下文下注意力分数漂移。其三，格式定义不等于吞吐收益：材料未给出硬件实测，把 MXFP4 的位宽账本直接当成端到端延迟下降是越界推断，真正的收益取决于反量化是否融合进 MMA、缩放因子读取是否与权重流重叠。</p>\n<p>KV cache 是这套账本最敏感的部分，因为它在解码阶段随 <em>B</em>×<em>S</em> 线性增长，而权重是静态的。以 MXFP8 KV（<em>b</em><sub>kv</sub>=8、<em>k</em>=32，有效 8.25 bit）对比 FP16 KV，容量约减半，但每步解码要额外读取缩放因子流：若 <em>H</em><sub>kv</sub>×<em>d</em> 较大，缩放因子的读取会与 KV 主体读取争用 HBM 带宽，带宽瓶颈从“读多少 KV”变成“读 KV 加读元数据”。因此分页粒度要与块大小对齐——页内块边界错位会导致跨页读取缩放因子，破坏合并访问；压缩与复用（如共享前缀的 KV 复用）也必须以块为单位做，否则复用命中后仍需重算缩放。卸载到主机侧时同理，MX 格式的元数据要随主体一起搬运，PCIe 上的有效字节数按 <em>b</em>+<em>e</em>/<em>k</em> 计，而不是按 <em>b</em> 计。</p>\n<table class=\"mini\"><thead><tr><th>项目</th><th>账本口径</th><th>系统代价</th></tr></thead><tbody><tr><td>权重 MXFP4，k=32</td><td>4.25 bit/元素</td><td>静态占用降，反量化需融合进 MMA</td></tr><tr><td>KV MXFP8，k=32</td><td>8.25 bit/元素</td><td>容量减半，缩放因子流争用带宽</td></tr><tr><td>块内离群值</td><td>s 被拉高</td><td>同块尾数精度下降，需缩块或旁路</td></tr></tbody></table>\n<p>可复算的预算流程是：给定参数量与层结构算出 <em>M</em><sub>w</sub>，给定 <em>L</em>、<em>H</em><sub>kv</sub>、<em>d</em> 与目标 <em>S</em> 算出单请求 KV 字节，再用 HBM3e 容量减去权重、激活峰值与框架开销得到可用 KV 池，除以单请求字节得到并发上限；随后用带宽账本校验解码步：每步需读的权重字节加 KV 字节加缩放因子字节，除以 HBM 带宽得到理论步时下限，若该下限已接近 SLO 的 TPOT 预算，则格式压缩的收益必须来自融合反量化减少的额外读写，而不是位宽本身。边界判断落在块大小上：<em>k</em> 增大省元数据但放大离群值风险，<em>k</em> 减小稳精度但抬高带宽与页对齐复杂度，这个折中点要按实际权重与激活的块内最大值分布来定，材料未给出该分布的统计，因此只能以离线校准的方式逐层测量后再冻结格式参数。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-27\">二十七 · 块缩放语义如何改写批调度的成本模型</h3>\n<p>在 MX 格式族里，批调度不再只是“把请求拼进一个 batch”的问题，而是先要决定“这一批张量按什么块粒度量化、缩放因子在哪里生成、元数据跟不跟数据一起搬”。块大小一旦固定，权重侧缩放因子是离线算好的常量，激活侧缩放因子却必须在线按块统计——<code>s = max|x_j| / q_max</code> 这一步在 prefill 阶段对每个 token 的每个块都要做一遍。连续批处理把不同长度请求拼进同一 step 时，激活张量的块边界会随拼接方式漂移：按行拼（token 维）时块内元素来自不同请求，按块统计最大值会把长请求的离群激活和短请求的平缓激活混进同一个缩放因子，短请求的有效尾数被拉低。这就是调度层必须感知格式语义的原因：批拼法直接决定量化统计的干净程度。</p>\n<p>代价体现在两处。其一是元数据带宽：块越小，缩放因子占比越高，反量化时每读一个数据块就要多读一个指数；块越大，离群值污染越严重。其二是算子融合深度：若矩阵乘在张量核心内融合反量化，缩放因子必须与数据同布局进 SMEM/TMEM，批调度产生的张量形状若不能对齐块边界，融合路径退化为先反量化再乘，多一次写回。工程判断是：调度器应把“块对齐”作为拼批约束之一，而不是拼完再量化。</p>\n<div class=\"formula\">$$\\text{meta\\_ratio}=\\frac{b_s}{b_s\\cdot w_e},\\qquad \\text{eff\\_bits}=w_e+\\frac{b_s}{b_s\\cdot w_e}\\text{（每元素摊到的缩放比特）}$$</div>\n<p>举例：一个 decode step 拼进 64 条请求，每条 1 个 token，若按 token 维拼成 64 行、块大小沿隐藏维切分，则每行独立统计缩放，互不污染；若按隐藏维跨请求拼，块内混入不同请求的激活分布，缩放被最大值主导。前者元数据量随行数线性增长但统计干净，后者元数据少但精度不可控——这正是 chunked prefill 与连续批处理必须联合设计的接口。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-28\">二十八 · 连续批处理与 chunked prefill 的块级耦合</h3>\n<p>连续批处理的核心是每 step 淘汰完成序列、插入新序列，使 decode 阶段 batch 始终填满。但 prefill 请求一旦整段插入，会瞬间拉长 step 时间，把在跑的 decode 请求的 ITL 打穿。chunked prefill 把长 prefill 切成固定 token 数的 chunk，与 decode 请求同 step 混跑，用算力换尾延迟平滑。在 MX 语义下，chunk 边界必须与块边界对齐：一个 chunk 的激活若在块中间截断，该块只能按不完整统计求缩放，反量化时与相邻 chunk 的缩放不一致，注意力 QK 乘里同一 token 的 Q 与 K 可能落在不同缩放块上，融合路径需额外做缩放重对齐。</p>\n<p>伪代码思路：调度器维护两个队列，decode 队列按剩余输出长度排序，prefill 队列按 chunk 序号排序；每 step 先按 token 预算 <code>B_tok</code> 取 decode 请求（每请求至少 1 token），剩余预算按块对齐向下取整分配给 prefill chunk。预算分配后，激活量化按 chunk 内完整块统计，跨 chunk 的尾块单独打标、走非融合反量化路径。</p>\n<ul>\n<li>机制：token 预算而非请求数预算，保证每 step 的计算量可预测，MX 块统计的在线开销随 token 数线性增长，可被预算封顶。</li>\n<li>代价：chunk 越小，prefill 尾延迟越平滑，但每 chunk 的固定开销（缩放因子生成、kernel launch、TMEM 装载）摊薄变差，吞吐下降；chunk 越大则相反。</li>\n<li>例子：一个 8k token 的 prefill 切成 512 token chunk，与 32 条 decode 请求混跑，decode 的 ITL 波动被压到单 chunk 计算时间内；若 chunk 取 2048，单 step 时间拉长，尾延迟回升。</li>\n</ul>\n<p>这里的关键取舍是：chunked prefill 改善的是尾延迟分布，代价是 prefill 自身的吞吐（块统计重复、缩放因子多次生成）。在块缩放格式下，这个代价比 FP16 路径更明显，因为每个 chunk 都要重新走一遍按块求最大值的归约。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-29\">二十九 · 优先级、抢占与 KV 的低精度重写</h3>\n<p>当显存逼近上限，调度器必须抢占：换出某些序列的 KV 腾空间。在 MX 路径上，KV cache 本身以块缩放低精度存储，换出再换入意味着反量化—搬移—再量化一轮，缩放因子随统计重算，若两次统计的块内最大值不同，换入后的 KV 与换出前数值不一致，注意力结果出现漂移。因此抢占策略要区分“可逆换出”与“有损换出”：前者保留缩放因子与低精度块原样搬到主机侧，换入时直接复用；后者在显存压力下丢弃缩放元数据只留元素，换入时重算，精度不可逆。</p>\n<p>优先级调度则要按 SLO 分层：交互式请求给短 ITL 目标，批式请求给吞吐目标。抢占时优先换出批式序列，因为其尾延迟容忍度高；交互式序列即使 KV 更长也保留在显存。代价是显存碎片化：不同序列的 KV 块大小与缩放因子布局不同，换出后留下的空洞难以被新序列的块对齐复用，需要按块大小分桶的空闲链表。</p>\n<table class=\"mini\"><thead><tr><th>策略</th><th>尾延迟</th><th>吞吐</th><th>KV 精度</th></tr></thead><tbody><tr><td>整段 prefill 插入</td><td>差（step 时间尖峰）</td><td>高</td><td>块统计完整</td></tr><tr><td>chunked prefill 混跑</td><td>好</td><td>中</td><td>尾块需单独处理</td></tr><tr><td>有损抢占换出</td><td>好（快速腾空）</td><td>高</td><td>换入重算，漂移</td></tr><tr><td>可逆换出保留缩放</td><td>中（搬移开销）</td><td>中</td><td>数值一致</td></tr></tbody></table>\n<p>具体例子：GB200 NVL72 单机架内多实例共享显存池时，一个长上下文交互请求的 KV 若被有损换出，换入后同一块的缩放因子因统计窗口变化而改变，QK 乘的 logits 出现系统性偏移，表现为回答质量下降而非报错——这类失败在监控上只体现为精度指标漂移，不会触发延迟告警，必须靠数值一致性校验捕获。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-30\">三十 · 分离式预填/解码的格式不对称</h3>\n<p>分离式架构把 prefill 与 decode 拆到不同实例：prefill 实例吃长 prompt、算力密集，decode 实例吃逐 token 生成、带宽密集。MX 格式在这两侧的性价比不对称：prefill 阶段激活块统计开销可被大矩阵乘摊薄，块缩放收益主要在权重带宽；decode 阶段每 step 只处理少量 token，激活量小，KV cache 的低精度存储成为带宽主项，块缩放直接决定 KV 读取带宽。因此分离式部署应让两侧使用不同的块大小与位宽组合：prefill 侧偏大块、低元数据占比以保吞吐，decode 侧偏小块、细统计以保 KV 精度。</p>\n<p>代价是跨实例传输：prefill 产出的 KV 要以 decode 侧约定的格式写回，若两侧块大小不同，需在传输前做一次重块化（re-blocking），把大块拆成小块并重算缩放，这一步在 NIXL/NVLink 传输路径上增加一次格式转换 kernel。转换的带宽开销与块大小比成正比，块越小转换越贵。工程判断是：两侧块大小取整数倍关系，重块化退化为子块切分而非重统计，缩放因子可由父块缩放按比例下推，避免逐子块归约。</p>\n<div class=\"formula\">$$s_{\\text{sub}}=\\frac{\\max_{j\\in \\text{sub}}|x_j|}{q_{\\max}}\\le s_{\\text{parent}},\\qquad \\text{若沿用 } s_{\\text{parent}} \\text{ 则子块有效位宽下降}$$</div>\n<p>例子：prefill 侧按 64 元素块量化 KV，decode 侧按 16 元素块读取，父块缩放直接下推到四个子块时，子块内若存在局部离群值，其尾数被父块缩放压制；若逐子块重算，则多四次归约。调度层需按 KV 的访问热度决定哪些块值得重算。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-31\">三十一 · 尾延迟的压缩手段与格式代价</h3>\n<p>尾延迟的来源在 MX 路径上被放大为三类：块统计的归约延迟（在线求最大值是串行依赖）、缩放因子编码的写回延迟、以及跨 chunk/跨实例格式不一致导致的额外 kernel。压缩手段对应三层：其一，把块统计与矩阵乘流水化，统计上一块的缩放同时算当前块的乘，用双缓冲隐藏归约延迟；其二，缩放因子用 E8M0 指数编码，编码本身是位操作，可与元素舍入同 kernel 完成，避免单独写回；其三，调度器按块对齐拼批，消除尾块的非融合路径。</p>\n<p>吞吐与尾延迟的取舍最终落在 token 预算与 chunk 大小的乘积上：预算越大、chunk 越大，单 step 计算越集中，吞吐越高但尾延迟尖峰越明显；反之尾延迟平滑但固定开销占比上升。可操作的判据是让单 step 时间不超过交互请求 ITL 目标的一个固定比例，剩余波动由 chunk 切分吸收。具体例子：ITL 目标 50 ms 量级时，单 step 预算应控制在使其计算时间显著低于该目标，chunk 取能整除块大小的最小值，使尾块浪费最小。</p>\n<p>最后落在机制上：调度器与量化器必须共享同一份块布局描述——块大小、缩放编码、对齐约束——否则拼批、chunk 切分、抢占换出、跨实例传输四个环节各自引入一次格式转换，尾延迟的方差被这些转换放大。把块布局作为调度的一等约束写进拼批决策，比事后在算子层做格式修补更能压住 p99。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-32\">三十二 · 块缩放语义如何约束调度粒度与抢占代价</h3>\n<p>MX 格式的调度影响不在请求层，而在“块”这一层：权重与激活按固定块大小切分，每块共享一个 E8M0 或 FP8 指数缩放因子，元数据比例由块大小决定。连续批处理把不同长度请求拼进同一 token 步时，激活张量的块边界会随批内序列拼接而错位，若算子按块融合反量化，就必须在拼接后重新按块统计最大值并重算缩放因子，这相当于在每步调度里插入一次块级量化开销。chunked prefill 把长预填切成固定 token 窗口，窗口大小若与块大小不成整数倍，尾部窗口会产生不满块，其缩放因子由少量元素的最大值推导，统计噪声放大，反量化误差在后续层累积。因此调度器切分粒度应与块大小对齐，否则省下的显存带宽会被重算缩放与不满块误差吃掉。</p>\n<p>优先级与抢占的代价同样落在块缩放语义上。解码阶段 KV 缓存以低精度按块存储，抢占驱逐某请求时，其 KV 块已被量化写回；恢复时若沿用旧缩放因子而不重新统计，块内离群值变化会使有效尾数精度漂移。设块内元素为 $x_j$，共享缩放 $s=\\max_j|x_j|/q_{\\max}$，则同块其余元素的有效量化步长为 $s$，块内动态范围被最大值独占。抢占恢复若触发重算，代价是一次按块读取加舍入；若不重算，代价是精度漂移。分离式预填/解码把预填与解码放到不同资源池，预填侧产出的 KV 块缩放因子必须随 KV 一起传输，否则解码侧无法正确反量化，NIXL 传输的元数据量随块数线性增长。</p>\n<p>尾延迟的压缩点在于避免“离群块”拖慢整批。块内离群值拉高共享缩放，压缩其余元素有效精度，这类块在注意力 QK 与 PV 乘中表现为反量化后累加结果偏差，迫使调度器要么缩小批以降低块统计方差，要么对离群块单独走更高位宽路径，两者都增加时延方差。工程判断是：块大小决定元数据带宽与统计粒度，调度窗口应取块大小的整数倍；抢占恢复必须重算缩放而非复用旧因子；分离式部署要把缩放因子纳入 KV 传输契约。材料未给出端到端吞吐与精度数字，不能把格式定义直接等同于调度收益。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-33\">三十三 · 切分维度与通信原语的对应关系</h3>\n<p>在 Blackwell 上谈并行，先要把“切什么”与“走哪条链路”对齐。张量并行（TP）切的是单层内的权重矩阵列或行，每层前向需要一次 All-Reduce 或两次 All-Gather/Reduce-Scatter 把部分和拼回完整激活；流水并行（PP）切的是层，跨 stage 只传边界激活，通信量正比于 <em>batch × seq × hidden</em>，但存在气泡；专家并行（EP）切的是 MoE 的专家集合，每个 token 经路由后被派发到持有目标专家的 rank，走的是 All-to-All，且是唯一随路由分布动态变化的集合通信；数据并行（DP）切的是样本，梯度侧在推理中不出现，推理里 DP 更多体现为副本间的请求分摊与 KV 前缀共享。四种切分的通信频次与消息尺寸差异极大：TP 每层都通信、消息小；PP 每 stage 一次、消息中等；EP 每 MoE 层两次 All-to-All、消息碎片化；DP 几乎不通信。</p>\n<p>把单次集合通信的代价写成可估算的形式，对 ring 算法有：</p>\n<div class=\"formula\">$$T_{\\text{coll}} \\approx \\underbrace{\\alpha \\log P}_{\\text{启动}}+\\underbrace{\\frac{S\\cdot (P-1)}{P\\cdot B_{\\text{link}}}}_{\\text{搬运}}$$</div>\n<p>其中 <em>α</em> 是单跳启动延迟，<em>S</em> 是消息字节数，<em>B<sub>link</sub></em> 是单链路有效带宽，<em>P</em> 是参与 rank 数。这个式子给出第一个工程判断：当 <em>S</em> 小到 <em>α</em> 项占主导时，增加并行度只会放大启动开销，TP 的收益在 hidden 较小时迅速衰减。Blackwell 的 NVLink 5 与 NVSwitch 把 <em>B<sub>link</sub></em> 抬到很高、把 <em>α</em> 压得很低，但 NVSwitch 的交换容量仍是共享资源，多组集合通信并发时会互相挤占。举例：GB200 NVL72 单机架 72 个 GPU 全互联，一个 8 路 TP 组做 All-Reduce 只跨机架内一跳，而跨两个 NVL72 机架的 16 路 TP 就要经过机架间链路，后者带宽档位与前者不同，拓扑感知的 rank 映射因此不是可选优化而是必需项。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-34\">三十四 · 块缩放格式如何改变通信账本</h3>\n<p>MX 格式对并行的直接影响不在算力侧，而在“传什么”。权重与激活按块共享缩放因子后，跨 rank 传输的张量由“高精度元素”变成“低精度元素 + 块级元数据”。设块大小为 <em>k</em>，元素位宽 <em>b</em>，缩放因子位宽 <em>e</em>，则有效每元素比特数为：</p>\n<div class=\"formula\">$$b_{\\text{eff}} = b + \\frac{e}{k}$$</div>\n<p>以 MXFP4 配 E8M0 缩放、块大小 32 为例，<em>b<sub>eff</sub></em> = 4 + 8/32 = 4.25 bit，相比 FP16 的 16 bit，跨 rank 搬运的字节数降到约四分之一。这直接改写第一节的搬运项：TP 的 All-Reduce 若在低精度域完成，<em>S</em> 缩小，通信从瓶颈退为次要项；但若框架选择“先反量化到 BF16 再 Reduce”，则格式带来的带宽收益在通信段被完全抵消。这是一个必须在实现层确认的语义问题：All-Reduce 的求和应在缩放因子的公共域上进行，还是各 rank 保留自己的块缩放、只归约量化后的整数？前者需要先把块缩放对齐（不同 rank 的同一块可能算出不同 <em>s</em>），后者精度更稳但要求算子理解块结构。</p>\n<p>代价举例：一个 EP 层的 All-to-All，token 激活若以 MXFP8 传输，消息尺寸减半，All-to-All 的搬运时间减半，但每个 token 的元数据（每块一个 E8M0 指数）要随 payload 一起走，路由实现必须把“块”与“token”两个切分维度对齐，否则接收端无法重建缩放。工程上常见的做法是把块大小选成 hidden 维的整除因子，让每个 token 的激活恰好是整数个块，元数据布局规整、可向量化读取。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-35\">三十五 · 通信何时成为瓶颈：三个判据</h3>\n<p>判据一，计算通信比。设单层矩阵乘的浮点运算量为 <em>F</em>，通信字节为 <em>S</em>，硬件算力 <em>C</em>、链路带宽 <em>B</em>，则通信隐藏的条件是 <em>F/C &gt; S/B</em>，即算术强度超过机器平衡点。TP 的 <em>S</em> 正比于激活尺寸而 <em>F</em> 正比于 <em>batch×seq×hidden×hidden</em>，所以 batch 或 seq 越大越容易隐藏通信；decode 阶段 seq=1、batch 受 KV 显存限制，算术强度低，TP 通信最容易暴露。这就是为什么分离式预填/解码里，decode 实例倾向用较小 TP 度、把并行度让给副本数。</p>\n<p>判据二，消息碎片化。EP 的 All-to-All 按 token 路由，每个 rank 发给每个 rank 的消息长度随路由分布波动，尾部 rank 决定整体完成时间。若某专家的负载因路由偏斜而集中，该 rank 的发送队列成为长尾，其余 rank 空等。块缩放格式在这里帮不上忙——它压缩的是字节数，不改变负载分布；缓解手段是容量因子与 token 丢弃策略，代价是精度。</p>\n<p>判据三，拓扑跳数。同一集合通信在 NVL72 机架内与跨机架的执行时间不在一个档位。把 TP 组约束在单机架内、把 PP 或 EP 的跨机架流量交给带宽较低的链路，是容量规划的基本约束。判据可写成：若某并行维度的通信量占单步时间的比例超过该维度带来的算力收益比例，则该维度不应继续扩大。举例：把 TP 从 8 扩到 16，单层计算时间减半但通信跳数增加、消息不变，净收益取决于 <em>α</em> 与 <em>B</em> 的实际档位——这正是需要实测而非纸面推导的地方。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-36\">三十六 · NIXL 与传输层：把 KV 当一等公民搬运</h3>\n<p>分离式推理把预填与解码拆到不同实例后，KV cache 成为跨节点传输的主体，其体量远超单层激活。NIXL 的定位是把“点对点大块内存搬运”从集合通信中独立出来：它做的是注册内存区域、建立传输描述符、按块异步拉取，而不是参与规约。对 MX 格式而言这层尤其关键：KV cache 若以块缩放低精度存储，传输的字节数按第二节的 <em>b<sub>eff</sub></em> 缩减，但接收端解码器必须知道每块的缩放因子布局，NIXL 的传输描述符需要携带块元数据的偏移，否则解码侧拿到的是无法反量化的裸比特。</p>\n<p>代价上，NIXL 路径的瓶颈通常不在链路带宽而在注册与描述符管理：大量小 KV 块（按 token 或按页切分）会产生大量描述符，启动开销累积。工程判断是把 KV 按页聚合、按层批量传输，让单次传输的消息尺寸落在带宽主导区间而非 <em>α</em> 主导区间。另一个代价是显存：低精度 KV 省下的显存可以换更大的 batch，但块缩放元数据本身占显存，块越小元数据比例越高，需要在“压缩率”与“元数据开销”之间取平衡点，这与格式设计里的块大小选择是同一个权衡在系统层的投影。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-37\">三十七 · 并行组合下的数值一致性</h3>\n<p>块缩放引入了一个并行特有的隐患：同一逻辑张量在不同 rank 上被切成不同的块边界。TP 按列切权重时，若切分点不落在块边界上，两个 rank 的同一行会属于不同块、带不同缩放因子，All-Reduce 归约后无法用单一缩放重建。解决方式是把切分粒度对齐到块大小，或在切分前完成量化、切分后只搬运“元素+缩放”的完整块。后者要求集合通信原语理解块结构，属于算子与通信协同设计的范畴。</p>\n<p>PP 侧的隐患是跨 stage 的重新量化：stage 边界输出若按块重新量化写回，下一 stage 读到的激活已经带了一次舍入误差，多层累积后与单卡路径的数值轨迹分叉。这与格式本身的舍入语义直接相关——论文强调缩放因子编码与舍入语义需与算子实现一致，在并行场景下这句话的含义是：所有 rank 必须用同一套块统计与舍入规则，否则归约前的部分和已经不可比。工程上的做法是把量化点固定在确定的层边界，让并行切分不改变量化发生的拓扑位置。</p>\n<p>代价举例：一个 4 路 TP、2 路 PP 的组合，若每 stage 边界做一次块重量化，端到端会多出若干次舍入；这些舍入不增加延迟，但改变了精度预算的分配，使低精度路径的误差边界更难界定。材料未给出该场景的精度实测，因此工程判断应保守：在并行度提高时同步收紧块大小或提高元素位宽，用格式参数换数值稳定裕度。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-38\">三十八 · 容量规划中的通信预算</h3>\n<p>把上述判据落到容量规划，需要为每条链路留出预算而不是等瓶颈出现再调。做法是：按目标 SLO 反推单 token 的时间预算，扣除计算时间后得到通信时间上限，再用第一节的公式反解可用的并行度与消息尺寸。对 MX 格式路径，这个反解要把 <em>b<sub>eff</sub></em> 代入 <em>S</em>，并显式计入元数据。举例：decode 实例的 TP 组若因 KV 读取带宽受限而无法靠增大 batch 提升算术强度，则通信预算被压缩，此时应优先降低 TP 度、增加 DP 副本，把 All-Reduce 换成请求级分摊——这是用调度换通信的典型取舍。</p>\n<p>最后落在具体机制上：Blackwell 的 NVSwitch 与 NVLink 5 提供了高带宽低延迟的集合通信底座，但块缩放格式的真正价值是把“传多少”这个变量交到格式设计者手里。块大小 <em>k</em> 一旦选定，元数据比例 <em>e/k</em> 就固定，通信账本随之固定；并行拓扑的选择本质上是在这个固定账本上做分配。工程判断因此很直接：先定格式与块大小，再定切分维度与 rank 映射，最后用实测的 <em>α</em> 与 <em>B</em> 校验预算是否成立——顺序颠倒会把格式收益浪费在错误的拓扑上。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-39\">三十九 · 块缩放语义在并行切分下的通信边界</h3>\n<p>MX 格式的元数据比例由块大小决定，这一点在并行切分里会直接改写通信账本。以块大小 32、元素 FP4 为例，每块 32 个 4 bit 元素共 16 字节，外加一个 E8M0 缩放因子 1 字节，元数据占比约 1/17；若块大小缩到 16，元数据占比翻倍。当张量按 TP 沿隐藏维切开、按 EP 沿专家维切开时，切分边界未必与块边界对齐：跨切分点的块需要在集合通信前重新打包缩放因子，否则接收方无法按块反量化。All-Reduce 的通信量不再只是元素位宽的函数，而是</p>\n<div class=\"formula\">$$B_{\\text{comm}} = N \\cdot \\left(b_e + \\frac{b_s}{k}\\right)$$</div>\n<p>其中 $N$ 为参与归约的元素数，$b_e$ 为元素位宽，$b_s$ 为缩放因子位宽，$k$ 为块大小。k 越小，块级动态范围适配越细，但通信与显存里的元数据开销线性上升；k 越大，离群值拉高共享缩放、压缩同块其余元素有效尾数的问题越突出。这是格式参数与并行拓扑之间必须联合决策的边界，而不是算子层单独能定的常量。</p>\n<p>通信何时成为瓶颈，取决于计算强度与链路带宽的比值。TP 的每层 All-Reduce 发生在矩阵乘之后，若单卡在低精度下的张量核心吞吐远高于 NVLink 5 的单向带宽，归约就会暴露在关键路径上；此时把激活按块量化传输，收益来自字节数下降，但代价是接收端必须先反量化再累加，或要求硬件在归约路径上支持块缩放语义，否则缩放因子与元素的分离传输会引入额外的一次小消息通信。EP 的 All-to-All 更敏感：专家并行下 token 被路由到不同设备，消息尺寸随批内路由分布剧烈波动，小块带来的元数据碎片会放大消息数量，NIXL 这类传输层若按块粒度注册与搬运，描述符开销可能吃掉位宽压缩的收益。PP 的边界激活传输量小但频率固定，块缩放语义需在 stage 间保持一致，否则跨 stage 反量化误差逐层累积。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>通信形态</th><th>块缩放引入的代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>缩放因子随激活同行传输，归约前需对齐块边界</td><td>计算强度不足以掩盖链路时延</td></tr><tr><td>EP</td><td>All-to-All</td><td>路由碎片化放大元数据消息数</td><td>批内路由分布长尾、消息过小</td></tr><tr><td>PP</td><td>边界点对点</td><td>stage 间缩放语义须一致</td><td>各 stage 采用不同块大小</td></tr><tr><td>DP</td><td>梯度/权重同步（推理侧多为权重加载）</td><td>权重按块压缩后加载带宽下降</td><td>缩放因子编码与算子实现不一致</td></tr></tbody></table>\n<p>工程判断落在两处：其一，块大小应按最窄的那条通信路径选取，而不是按单算子精度最优选取——若 EP 的 All-to-All 是主导瓶颈，放大块大小以减少元数据碎片，比在 TP 上追求更细的动态范围更划算；其二，缩放因子的编码与舍入语义必须与集合通信和 NIXL 搬运路径的实现严格一致，任何一处按元素而非按块处理，都会让反量化误差在多层、多 stage 上累积，而材料未给出该误差边界的量化结果，因此不能把格式定义直接等同于端到端吞吐收益。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-40\">四十 · 精度塌陷：块内离群值如何吃掉尾数</h3>\n<p>MX 格式的精度风险不在“平均误差”，而在块内分布的偏斜。缩放因子按块内绝对值最大值推导，一个离群元素就把整块的 <span>s</span> 抬高，同块其余元素除以这个偏大的 <span>s</span> 后落入更低的量化档位，尾数有效位被压缩。对 FP4 元素位宽，这种压缩是致命的：可表示值稀疏，舍入误差迅速放大。诊断时不要只看整层余弦相似度，要按块统计“离群块占比”与“块内动态范围比”——即块内最大值与次大值之比。当某层该比值持续偏高，说明块切分与离群值位置错位。</p>\n<div class=\"formula\">$$\\mathrm{eff\\_bits}\\approx \\log_2\\!\\left(\\frac{\\max_{j\\in B}|x_j|}{\\mathrm{median}_{j\\in B}|x_j|}\\right)^{-1}\\cdot b_{\\text{elem}}$$</div>\n<p>工程上更可靠的定位手段是逐层输出比对：把同一批校准输入分别喂给高精度参考路径与 MX 路径，按块记录反量化后的相对误差，找出误差在层间累积的拐点。注意力链路尤其敏感，QK 与 PV 乘沿用块缩放语义，若 Q 与 K 的块切分不对齐，点积的缩放因子在累加时被反复引入，误差随序列长度增长。代价是显存带宽：为了做逐块比对，需要把高精度参考权重额外驻留一份，短时占用可观，通常只在诊断窗口开启，不进入常驻服务。</p>\n<p>具体例子：某层权重矩阵按 32 元素块切分，某块含一个幅值约为其余元素十倍的离群权重，缩放因子被该值主导，其余元素量化后大量落入零或相邻档位；该层输出在长序列末尾出现可见漂移，而整层平均误差指标仍显示正常。这说明监控指标必须按块、按层、按 token 位置三维切片，单一全局指标会掩盖塌陷。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-41\">四十一 · OOM 与批抖动：元数据、KV 与瞬时峰值</h3>\n<p>MX 格式的显存账本不只是元素位宽。每块附带一个缩放因子，块越小元数据比例越高；块大小决定元数据开销与统计粒度，二者直接冲突。把块从 32 缩到 16 提升动态范围适配，却让缩放因子数量翻倍，显存占用与带宽同步上升。OOM 往往不是稳态超限，而是批调度器在连续批处理中把新请求拼进已有批时，瞬时激活峰值叠加 KV 增长所致。诊断要看“批内 token 数 × 每 token 激活字节 + KV 增量”的瞬时和，而非平均占用。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{N_{\\text{tok}}\\cdot d\\cdot b_{\\text{act}}}_{\\text{激活}}+\\underbrace{N_{\\text{tok}}\\cdot d\\cdot b_{\\text{act}}/b_{\\text{blk}}\\cdot b_{s}}_{\\text{缩放元数据}}+\\underbrace{2\\cdot L\\cdot H\\cdot N_{\\text{ctx}}\\cdot b_{\\text{kv}}}_{\\text{KV}}$$</div>\n<p>批抖动的典型症状是吞吐随并发非单调：并发上升后每步延迟跳变，调度器为守住显存上限频繁拆分与重组批，GPU 利用率出现锯齿。定位方法是给调度器打点，记录每次批组成变化前后的显存水位与步进时间，找出触发拆批的水位阈值。回滚策略上，优先降块内元素位宽之外的维度——先缩批上限、再降 KV 精度、最后才动块大小，因为改块大小会同时改变算子语义与元数据布局，回滚成本最高。</p>\n<p>具体例子：某服务在并发爬升时出现周期性 OOM，日志显示失败总发生在预填与解码混合批的拼接瞬间；把预填请求单独成批、解码批设硬上限后，峰值显存回落，抖动消失。代价是预填与解码分离带来额外的 KV 传输与调度开销，需在吞吐与稳定性间取舍。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-42\">四十二 · 尾延迟：缩放读取与反量化的串行代价</h3>\n<p>块缩放算子的尾延迟来源是缩放因子的读取路径。矩阵乘按块读取缩放并在张量核心内融合反量化，若缩放因子未与元素同址预取，算子会在每个块边界产生一次额外访存，形成周期性停顿。批内序列长度不齐时，短序列先完成、长序列拖尾，尾延迟由最长序列的块遍历次数决定。诊断要采集分位数延迟与每步的块边界停顿计数，而不是只看均值。</p>\n<div class=\"formula\">$$T_{\\text{tail}} \\approx \\frac{N_{\\text{ctx}}}{b_{\\text{blk}}}\\cdot\\left(t_{\\text{elem}}+t_{s}\\right)+T_{\\text{sched}}$$</div>\n<p>降低尾延迟的机制是缩放因子预取与块对齐：把缩放因子按与元素相同的块序排布，使一次宽访存同时取回元素与缩放；对变长批做块级填充对齐，避免同批内块边界错位导致的重复读取。代价是带宽：预取放大了一次读取的粒度，短块场景下可能读到无用数据，需按实际块利用率决定是否开启。监控上应把“块边界停顿占比”作为独立指标，与尾延迟分位数联动观察。</p>\n<p>具体例子：某解码服务 P99 延迟明显高于 P50，剖析显示长上下文请求在注意力 PV 乘中每块触发一次缩放读取，块数随上下文线性增长；改为缩放因子与元素交错排布后，停顿计数下降，尾延迟收敛。注意这里只定性描述机制，具体收益取决于块大小与访存对齐。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-43\">四十三 · 静默降级：语义不一致与多层累积</h3>\n<p>最危险的失败模式是不报错但精度缓慢劣化。缩放因子编码与舍入语义若与算子实现不一致——例如量化端按就近取整、算子端按截断反量化，或 E8M0 指数编码的边界处理不同——误差不会在单层显现，而会在多层前向中累积。诊断手段是语义一致性校验：用同一组块数据分别走量化端与算子端的反量化路径，逐块比对结果位模式，任何偏差都意味着语义裂缝。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{accum}} \\approx \\sum_{l=1}^{L}\\varepsilon_{l},\\quad \\varepsilon_{l}=\\left|\\hat{x}_{l}-x_{l}\\right|/\\left|x_{l}\\right|$$</div>\n<p>监控静默降级要靠端到端质量探针而非算子级指标：固定一批探针请求，周期性比对输出分布偏移与任务级指标（如生成一致性、检索命中），一旦偏移越过阈值即触发告警。代价是探针请求占用推理容量，通常以低优先级、低并发注入。回滚路径必须可灰度：按层或按模块切回高精度路径，而不是整模型回退，以缩小性能损失面。</p>\n<p>具体例子：某部署在切换块大小后未同步更新算子端的缩放读取步长，反量化读到了错位的缩放因子，单层误差微小、整网输出逐步漂移，探针指标在数小时后才越线；按模块灰度回滚并修正步长后恢复。这类故障的根因是格式语义与算子实现脱节，而非格式本身。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-44\">四十四 · 监控与回滚的工程闭环</h3>\n<p>把上述失败模式收敛成一套可执行的监控面：块级离群统计、瞬时显存峰值、块边界停顿计数、语义一致性校验、端到端探针偏移，五类指标分别对应精度塌陷、OOM、尾延迟、静默降级与批抖动。每类指标都要绑定一个明确的回滚动作与灰度粒度。回滚顺序应遵循“改动面最小”原则：先调调度参数，再调 KV 精度，再切模块精度路径，最后才动块大小与元素位宽组合——后者同时改变格式语义、元数据布局与算子实现，是回滚链上代价最高的一环。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>关键指标</th><th>定位手段</th><th>回滚粒度</th></tr></thead><tbody><tr><td>精度塌陷</td><td>块内动态范围比、离群块占比</td><td>逐块反量化误差比对</td><td>按层切回高精度</td></tr><tr><td>OOM</td><td>瞬时显存峰值、批组成变化</td><td>调度器水位打点</td><td>缩批上限、分离预填</td></tr><tr><td>批抖动</td><td>步进时间锯齿、拆批频次</td><td>批重组前后水位对比</td><td>调度参数</td></tr><tr><td>尾延迟</td><td>P99、块边界停顿占比</td><td>缩放预取与块对齐剖析</td><td>块排布与填充策略</td></tr><tr><td>静默降级</td><td>探针分布偏移、语义校验偏差</td><td>量化端与算子端位模式比对</td><td>按模块灰度</td></tr></tbody></table>\n<p>工程判断落在一点：MX 格式的收益是带宽与显存的结构性节省，但它的失败模式全部集中在“块”这个粒度上——块内分布、块边界访存、块级语义一致性。监控与回滚的设计必须围绕块展开，把块级指标作为一等公民，而不是把格式当作一个黑盒位宽开关。当块级指标与端到端探针同时越线时，优先怀疑语义不一致而非数值精度本身，因为前者不报错、只漂移。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-45\">四十五 · 块缩放格式的失效边界：从离群块到静默精度漂移</h3>\n<p>MX 格式的失败很少以“报错”形式出现，而是以数值语义与算子实现之间的缝隙形式出现。最典型的失效条件是块内离群值：缩放因子由块内绝对值最大值推导，一个离群元素会把整块的 <span>s</span> 抬高，同块其余元素除以 <span>s</span> 后落入更低的量化格点，有效尾数被压缩。设块内元素动态范围为 <span>R = max|x_j| / median|x_j|</span>，则非离群元素损失的有效位数近似为 <span>log2(R)</span> 位——块越小，离群值污染面越小，但元数据比例上升；块越大，元数据省了，精度塌陷面却扩大。这是格式定义层面的固有边界，不是实现 bug，因此诊断时必须把“块大小 × 元素位宽”当作一个联合配置项来定位，而不是单独调其中一个。</p>\n<p>第二类失效是缩放因子编码与舍入语义的不一致。E8M0 指数只能表示 2 的幂，块内实际需要的 <span>s</span> 被向上取整到最近的幂次，等价于对整块施加了一个额外的增益偏差；若算子层在矩阵乘中融合反量化时用了不同的舍入方向（例如就近取整与向零截断混用），误差不会在单层显现，而是在注意力 QK、PV 与逐元素归一化之间逐层累积，表现为长上下文下输出分布的缓慢偏移——即静默降级。诊断手段不是看单算子误差，而是按块统计反量化前后的相对误差 <span>e_B = |x_i - s·q_i| / max_j|x_j|</span> 的分布，若某一层 <span>e_B</span> 的尾部明显厚于相邻层，就说明该层的缩放编码或舍入路径与算子实现脱节。</p>\n<p>系统代价上，块缩放格式的收益必须与元数据带宽一起核算。每块一个缩放因子的额外读取量为 <span>M = N / B · b_s</span>（<span>N</span> 为元素数，<span>B</span> 为块大小，<span>b_s</span> 为缩放因子位宽），当 <span>B</span> 缩小以抑制离群污染时，<span>M</span> 线性上升，直接吃掉低位宽带来的显存与带宽节省；在解码阶段 KV 缓存按块重新量化写回时，这部分元数据还会随序列长度增长而放大。因此“精度不够就调小块”是一条有明确代价曲线的操作，而非免费旋钮。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷（某层输出分布偏移）</td><td>按块统计 <span>e_B</span> 尾部厚度，比对相邻层</td><td>该层回退到 MXFP8 或逐通道缩放</td></tr><tr><td>显存 OOM / 批抖动</td><td>核算 <span>M</span> 与 KV 低精度写回增量</td><td>放大块大小或对 KV 保留高精度缩放</td></tr><tr><td>尾延迟抬升</td><td>分离反量化融合路径与元数据读取路径的耗时</td><td>算子层改为张量核心内融合缩放</td></tr></tbody></table>\n<p>工程判断落在监控粒度上：块缩放格式的健康指标不是全局 loss 或单点精度，而是按层、按块的反量化误差分布与元数据带宽占比。把这两项纳入在线监控，才能在精度塌陷演化为静默降级之前触发回滚；而回滚的最小单元应是单层格式档位，而非整模型，否则一次离群块污染会导致整个低精度部署路径被放弃。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-46\">四十六 · 论文的基准口径：格式定义不是性能声明</h3>\n<p>《Microscaling Data Formats for Deep Learning》给出的是一套格式语义与数值分析，而不是端到端推理基准。材料明确：未给出具体数据集、未给出硬件档位、未给出批大小与并发、未给出请求长度分布与 SLO，也未给出吞吐或精度对比数字。因此本部分的第一条口径是：任何把 MXFP4／MXFP6／MXFP8 的格式定义直接换算成 B200 上的 tokens/s 或显存占用的做法，都属于口径越界。论文可支撑的指标只有格式层可推导的量：元数据比例、块内有效尾数精度、反量化所需的额外读取与乘加。工程读者在引用这篇工作时，应把它当作“语义基线”，而不是“性能基线”。</p>\n<p>格式层的元数据比例可以直接算。设块大小为 <span class=\"inline-math\">B</span>，元素位宽为 <span class=\"inline-math\">b</span>，缩放因子编码位宽为 <span class=\"inline-math\">e</span>（E8M0 即 8 位指数），则每块比特数为 <span class=\"inline-math\">B·b + e</span>，相对纯低精度元素的元数据开销为：</p>\n<div class=\"formula\">$$\\eta=\\frac{e}{B\\cdot b},\\qquad \\text{有效位宽}=b\\,(1+\\eta)$$</div>\n<p>块越小，<span class=\"inline-math\">\\(\\eta\\)</span> 越大，显存与带宽代价越高；块越大，统计粒度越粗，离群值拉高共享缩放的风险越大。这是论文留给工程侧唯一可定量推演的权衡轴，也是后续硬件块缩放（如 NVFP4 的块粒度）必须继承的口径。举例：若 <span class=\"inline-math\">B=32</span>、<span class=\"inline-math\">b=4</span>、<span class=\"inline-math\">e=8</span>，则每 32 个元素携带 8 位元数据，有效位宽从 4 抬到约 4.25；若 <span class=\"inline-math\">B=16</span>，同样元素位宽下有效位宽抬到约 4.5。这个差值在权重常驻显存与 KV 带宽上都会被放大，但论文没有给出放大后的实测数字。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-47\">四十七 · 硬件档位与 batch／并发：论文未给的三个空格</h3>\n<p>材料写明“硬件档位未给出，未涉及 B200／B300／GB200 NVL72 具体部署”“并行拓扑未给出”“批大小与并发未给出”。这意味着论文的数值结论不携带任何 SM100/SM103 的档位信息。工程侧要做的不是替论文补数字，而是把三个空格显式标注出来，防止下游把格式语义误当成档位结论。具体机制上，块缩放格式在 Blackwell 上的落地依赖张量核心对块缩放的原生支持与 TMEM 的累加路径；论文只定义了“按块读取缩放、块内反量化后累加或融合缩放”的算子语义，没有规定缩放因子在片上如何驻留、是否与 MMA 指令捆绑。因此同一格式在不同档位、不同并行拓扑下的实际代价可以差出一个量级，而论文对此保持沉默。</p>\n<p>batch 与并发的影响同理。块缩放格式的收益主要落在权重与激活的存储与传输上，属于带宽侧；而 TTFT 受预填阶段的算力与显存带宽共同约束，TPOT 受解码阶段的 KV 读取带宽与批内并行度约束。论文没有给出请求长度分布，也没有给出连续批处理下的批组成，所以无法把格式的元数据开销映射到 TTFT／TPOT 的分解上。工程判断是：引用该论文时，只能声明“格式在块粒度上提供了动态范围适配语义”，不能声明“在该档位、该并发下 TTFT 降低多少”。</p>\n<p>一个具体例子：若把 MXFP8 用于权重、MXFP4 用于激活，块大小取 32，则在预填阶段，激活的块缩放元数据会随每次前向重新生成，元数据的读写进入带宽账；在解码阶段，权重常驻，元数据只读一次，代价被摊薄。论文未给出这两段的比例，因此不能把“格式省带宽”直接等同于“解码更快”。这条判断对容量规划尤其重要：显存预算要按 <span class=\"inline-math\">\\(b(1+\\eta)\\)</span> 计，而不是按标称位宽计。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-48\">四十八 · 指标口径：TTFT／TPOT／吞吐／显存／功耗各自能挂什么</h3>\n<p>把论文的格式语义挂到五类指标上，需要逐项确认“可挂”与“不可挂”。TTFT 的可挂部分是预填阶段权重与激活的读取字节数，因为块缩放直接改变字节数；不可挂部分是算力利用率与调度排队，论文未涉及。TPOT 的可挂部分是解码阶段权重读取与 KV 读取的字节数；不可挂部分是批内并行度与投机解码的接受率。吞吐的可挂部分只有“单位字节可承载的元素数”，即 <span class=\"inline-math\">\\(1/(b(1+\\eta))\\)</span> 的相对关系；绝对吞吐不可挂。显存的可挂部分是权重与 KV 的常驻字节数，按有效位宽折算；不可挂部分是碎片与预留。功耗完全不可挂：论文没有给出任何功耗测量，块缩放对功耗的影响只能定性说“带宽侧压缩通常伴随功耗下降”，但这不是论文的结论。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>论文可支撑的口径</th><th>不可挂的口径</th></tr></thead><tbody><tr><td>TTFT</td><td>预填读取字节按有效位宽折算</td><td>算力利用率、排队延迟</td></tr><tr><td>TPOT</td><td>解码权重与 KV 读取字节折算</td><td>批内并行度、接受率</td></tr><tr><td>吞吐</td><td>单位字节元素数的相对关系</td><td>绝对 tokens/s</td></tr><tr><td>显存</td><td>权重与 KV 常驻字节按 b(1+η) 计</td><td>碎片、预留、峰值</td></tr><tr><td>功耗</td><td>无</td><td>任何功耗数字</td></tr></tbody></table>\n<p>这张表的用法是：在容量规划表里，只允许把“显存”与“带宽”两列的数值按有效位宽改写，其余列保持原档位的实测值不动。任何把吞吐列也按位宽比例缩放的表格，都是把格式语义当成了性能模型，属于不可比。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-49\">四十九 · 哪些提升不可比：四类常见误读</h3>\n<p>第一类误读是把块级缩放与整张量缩放的精度差当成“格式带来的端到端提升”。论文明确缺少与逐张量缩放、逐通道缩放方案的定量精度对比，块大小与位宽组合的精度损失边界也未量化。因此“MXFP4 比整张量 FP4 精度高”只能作为定性方向，不能作为可比数字。第二类误读是把格式定义等同于硬件收益：材料写明“不能把格式定义直接等同于端到端推理吞吐收益”，因为缩放因子编码与舍入语义必须与算子实现一致，否则反量化误差会在多层累积，收益被误差抵消。</p>\n<p>第三类误读是跨块大小比较。不同块大小对应不同的元数据比例与统计粒度，两个实验若块大小不同，其精度与带宽代价不在同一口径上，不能直接比。第四类误读是跨档位比较：论文未涉及 B200／B300／GB200 NVL72，任何把论文的格式语义与某档位的实测吞吐并列的表格，都缺少共同的硬件口径。工程上应把这类表格拆成两栏：一栏是格式语义（可跨档位复用），一栏是档位实测（不可跨档位复用）。</p>\n<p>一个具体例子：某团队在自建集群上测得 MXFP8 权重 + MXFP4 激活的吞吐高于 FP8 基线，随后在报告中引用本论文作为“格式依据”。这在口径上是成立的，但必须同时标注：吞吐数字来自自建集群的档位与批组成，论文未提供该档位与批组成，因此该数字不可与论文的任何结论并列，也不可外推到 NVL72 的机架级部署。否则读者会把“格式语义的普适性”误读为“性能数字的普适性”。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-50\">五十 · 失败模式如何进入基准读法</h3>\n<p>论文列出的失败模式直接决定基准该怎么读。块内离群值会拉高共享缩放因子，压缩同块其余元素的有效尾数精度；这意味着同一格式在不同权重分布上的精度表现不可比，因为离群值的块内占比不同。基准报告若不给出块内最大值分布或离群值统计，其精度数字就缺少可比前提。材料写明“离群值块对缩放因子的影响未给出统计”，所以论文本身也无法提供这个前提。工程侧的补救是把块大小与统计方式作为基准配置的一部分显式记录，而不是只记录元素位宽。</p>\n<p>第二个失败模式是缩放因子编码与舍入语义需与算子实现一致，否则反量化误差在多层累积。这对应一个基准读法：两个实现若缩放因子编码不同（E8M0 与 FP8 指数），即使标称同一 MXFP 格式，其误差累积路径也不同，精度数字不可直接比。第三个失败模式是缺少硬件实测，因此任何“格式已就绪”的判断都缺少端到端证据。基准报告应把“格式语义验证”与“端到端服务验证”分成两节，前者可引用论文，后者必须自测。</p>\n<p>伪代码思路如下，用于在自测中固定口径：</p>\n<div class=\"formula\">$$\\text{for each block } B:\\; s=\\frac{\\max_{j\\in B}|x_j|}{q_{\\max}},\\; q_i=\\mathrm{round}(x_i/s)$$</div>\n<p>自测时必须同时记录 <span class=\"inline-math\">B</span>、<span class=\"inline-math\">b</span>、<span class=\"inline-math\">e</span>、舍入方式与块内最大值分布，缺一项则该组精度数字不可与他组并列。代价上，记录这些统计本身要额外读一遍权重，属于一次性离线开销，不进入服务延迟；但若在线上动态统计，则会进入预填带宽账，需与块缩放元数据的读写一并计入。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-51\">五十一 · 工程判断：把论文放在语义层，把数字留给自测</h3>\n<p>落到具体机制上，本论文对推理系统的可交付物是三条：块大小与元素位宽的组合语义、缩放因子的编码与反量化语义、以及块级动态范围相对整张量缩放的定性优势。这三条可以直接写进算子契约与格式转换工具，作为 NVFP4 类部署路径的上游语义。但它们不构成任何档位、任何 batch、任何并发下的性能承诺。工程判断因此是：在容量规划与 SLO 表中，格式语义只改写“字节数”一列，其余列必须来自本档位自测；在基准报告中，格式语义与端到端数字分节呈现，跨块大小、跨编码、跨档位的数字一律标注不可比。</p>\n<p>一个具体机制例子：把权重从 FP8 转为 MXFP4 时，若块大小取 32，则每 32 个权重携带 8 位 E8M0 缩放，权重常驻显存按有效位宽约 4.25 位折算；若同一模型的激活也走 MXFP4，则预填阶段每次前向都要重算激活的块缩放，元数据读写进入带宽账。前者是显存收益，后者是带宽代价，两者不在同一指标上，不能合并成一个“加速比”。这正是论文口径的核心：格式提供的是块级动态范围适配，收益落在哪个指标上，取决于该指标是否由字节数主导，而这必须由自测回答，论文不回答。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-52\">五十二 · 块缩放格式的基准口径：哪些数字能比，哪些不能</h3>\n<p>MX 格式的收益必须落在“同一量化语义、同一算子实现”这条线上才可比。块大小 B 决定元数据比例：每 B 个元素携带一个缩放因子，若缩放用 E8M0 即 8 bit，则额外位宽开销为 8/B bit/元素；B=32 时约 0.25 bit/元素，相对 FP4 的 4 bit 是约 6% 的存储增量，但换来块级动态范围。反量化乘法的算力代价可写成每元素一次乘加，融合进张量核心则摊薄到 MMA 指令内部；若算子未融合、需先物化反量化后的高精度块，则显存往返带宽会吃掉格式收益。因此读任何 MXFP4 吞吐数字前，先确认三件事：块大小与缩放编码是否与硬件张量核心的原生块缩放一致、反量化是融合还是分离、基线是 FP8 还是 FP16。</p>\n<div class=\"formula\">$$\\text{元数据开销}=\\frac{b_s}{B}\\ \\text{bit/元素},\\qquad \\text{有效精度}\\approx \\text{元素尾数位}-\\log_2\\!\\Big(\\frac{\\max_{j\\in B}|x_j|}{\\text{块内次大值}}\\Big)$$</div>\n<p>第二个公式给出失效条件的定量直觉：块内最大值与次大值差距越大，共享缩放被离群值抬高，其余元素的有效尾数位被压缩得越多。这意味着 MX 的精度损失不是均匀的，而是集中在“含离群值的块”上；块越小，离群值污染范围越小但元数据比例越高，块越大则相反。工程上判断一个 MXFP4 精度报告是否可信，要看它是否报告了逐块动态范围的分布，而不只是整网平均误差——平均误差会掩盖少数高动态范围块上的灾难性舍入。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比条件</th><th>不可比的典型情形</th></tr></thead><tbody><tr><td>batch / 并发</td><td>同 TTFT 约束下的并发数</td><td>大 batch 吞吐对比小 batch 延迟</td></tr><tr><td>指标</td><td>TTFT、TPOT、显存、功耗同报</td><td>只报 tokens/s 不报 TPOT</td></tr><tr><td>基线精度</td><td>FP8 或 FP16 同算子</td><td>FP16 基线配未融合反量化</td></tr><tr><td>模型与负载</td><td>同权重、同请求长度分布</td><td>预填为主对比解码为主</td></tr></tbody></table>\n<p>材料未给出硬件档位、批大小、并发与 SLO，也未给出端到端吞吐与显存实测，因此本卷不引用任何 MX 相关的加速比数字；格式定义与数值语义不等于部署收益。可迁移的工程判断是：把 MX 的评估拆成三层——格式层看元数据比例与缩放编码是否匹配硬件、算子层看反量化是否融合进 MMA 与注意力 QK/PV、服务层看 TTFT/TPOT/显存/功耗是否在同一并发与 SLO 下同报。任何跨层直接相乘得出的“端到端提升”都不可比，尤其在预填与解码占比不同的负载上，块缩放对带宽敏感的解码阶段与对算力敏感的预填阶段贡献完全不同。</p>\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-53\">五十三 · 迁移到非 Transformer 主干：块统计假设先失效</h3>\n<p>MX 格式的量化语义建立在一条隐含假设上：同一固定块内的元素属于同一统计分布，块内最大值能代表该块的动态范围。这条假设在 Transformer 的权重矩阵上大体成立，因为权重按输出通道组织、激活按 token 组织，块切分与矩阵乘的 K 维对齐后，块内元素量级相近。迁到卷积主干或混合专家结构时，假设先崩。卷积核的权重在空间维上高度相关，但按行主序切块会把不同输出通道的元素塞进同一块，块内最大值被某个大通道拉高，其余通道的有效尾数被压缩——这正是论文自己指出的“块内离群值拉高共享缩放”的失败模式，只是换了个触发位置。</p>\n<p>工程上的判断是：迁移前先确认块切分轴与数据布局的对应关系。若算子按 K 维做 MMA，块就必须沿 K 维连续切分，让缩放因子与 MMA 的累加步长对齐；若框架的权重布局是 NHWC 而块按 NCHW 切，反量化时缩放因子的读取会变成跨步访问，带宽开销直接翻倍。公式层面，块缩放本身不变：</p>\n<div class=\"formula\">$$x_i = s \\cdot q_i,\\quad s = \\frac{\\max_{j\\in B}|x_j|}{q_{\\max}},\\quad q_i=\\mathrm{round}\\left(\\frac{x_i}{s}\\right)$$</div>\n<p>变的是块边界 B 的定义。MoE 是更尖锐的例子：每个专家的权重矩阵独立量化时块统计干净，但若把多专家权重拼成一个大矩阵再切块，块内会混入不同专家的量级，缩放因子失去意义。代价体现在显存带宽上——元数据比例由块大小决定，块越小元数据越多，而跨步读取让有效带宽利用率下降；反过来块越大，块内离群值污染概率越高。这个权衡没有通用解，只能按主干的统计结构逐层定。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-54\">五十四 · 迁到视觉与扩散负载：激活分布与时间步耦合</h3>\n<p>扩散模型的推理链路与自回归解码不同：激活不是逐 token 流式产生，而是整张特征图在多个去噪步之间反复读写。把 MX 格式直接套上去，会遇到两个具体机制问题。其一是时间步耦合：同一层在不同去噪步的激活动态范围差异显著，早期步的激活幅值大、后期步趋于平缓，若缩放因子在每步按块重算，量化误差随步数累积；若跨步复用缩放因子，早期步的大幅值会把缩放拉高，后期步的有效精度被浪费。其二是空间相关性：特征图相邻像素高度相关，块内最大值往往由局部边缘主导，平坦区域元素的尾数精度被无谓牺牲。</p>\n<p>可行的改法是让缩放因子的统计窗口与去噪调度对齐——按时间步分组统计，或在块内采用更稳健的统计量替代纯最大值。代价是元数据从每块一个缩放变成每块每步一个缩放，显存占用上升；若把缩放因子缓存在片上而非写回 HBM，则受 TMEM 容量约束，块大小不能无限缩小。一个具体例子：视频扩散的潜空间张量在时间维上展开后，块若跨帧切分，帧间运动导致的幅值差异会污染缩放；按帧内切块则元数据量随帧数线性增长。这里的工程判断是：扩散负载上 MX 的收益主要来自权重侧，激活侧的低精度收益被时间步重算的元数据开销部分抵消，迁移时应优先量化权重、对激活保留更高位宽或更细的块粒度。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-55\">五十五 · 迁到长上下文与 KV cache：块粒度与缓存布局冲突</h3>\n<p>KV cache 的低精度存储是 MX 格式最诱人的迁移目标，也是最容易踩坑的地方。KV cache 的布局是 [层, 头, token, 维度]，块若沿 token 维切分，缩放因子随 token 增长而线性增长，元数据带宽占比在长上下文下不可忽略；块若沿头维切分，不同头的数值量级差异大，块内最大值被某个头主导。更麻烦的是写入路径：解码阶段每个新 token 只追加一行，按块量化要求凑满一个块才能算缩放，未满块要么暂存高精度、要么用填充值补齐，前者增加显存、后者引入误差。</p>\n<p>伪代码层面的处理思路是延迟量化：新 token 先以高精度写入暂存区，块凑满后一次性量化并写回低精度区，缩放因子随块一起落盘。代价是暂存区占用与一次额外的读写往返，在 decode 阶段每 token 的延迟里体现为固定开销。规模上限也在这里：上下文越长，块数越多，缩放因子的元数据总量越大，若元数据放在 HBM 而元素放在 HBM，两者竞争同一带宽预算，低精度带来的带宽节省被元数据吃掉一部分。判断是：KV cache 上 MX 的净收益取决于块大小与上下文长度的比值，短上下文收益明确，超长上下文需要把缩放因子压缩编码（如 E8M0 指数本身已是极简编码）或分层缓存，否则迁移收益递减。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-56\">五十六 · 规模上限：块大小、位宽与算子融合深度的三重约束</h3>\n<p>MX 格式的规模上限不是由格式定义决定的，而是由三个工程约束的交集决定。第一是块大小：块越小，块级动态范围适配越精细，但元数据比例越高，且 MMA 指令的 K 维步长要求块大小是硬件粒度的整数倍，块大小不能任意取。第二是元素位宽：FP4 的尾数位极少，块内元素共享缩放后，靠近块最大值的元素精度尚可，远离最大值的元素尾数被截断严重，位宽越低对块内分布均匀性的要求越苛刻。第三是算子融合深度：反量化若不能融合进 MMA，就要把低精度元素读进寄存器、反量化、再送入张量核心，多一次寄存器往返与指令开销；融合得越深，块缩放语义越要跟硬件指令的缩放模式严格对齐，否则误差在多层累积。</p>\n<table class=\"mini\"><thead><tr><th>约束</th><th>收紧方向</th><th>推理系统代价</th></tr></thead><tbody><tr><td>块大小</td><td>缩小以细化统计</td><td>元数据带宽占比上升，MMA 对齐受限</td></tr><tr><td>元素位宽</td><td>降至 FP4</td><td>块内分布不均时尾数精度骤降</td></tr><tr><td>融合深度</td><td>加深至张量核心内</td><td>缩放语义须与硬件模式逐位一致</td></tr></tbody></table>\n<p>规模上限的具体表现是：当模型层数增加、每层都做块量化时，单层的舍入误差虽小，但误差沿层累积，若缩放因子编码与算子实现的舍入语义不一致（例如一处用就近取整、另一处用截断），累积误差会放大。论文材料未给出块大小与位宽组合的精度损失边界，这意味着迁移时不能假设某个组合普适，必须按目标模型逐层做误差探测。判断是：MX 的规模上限由“块统计有效性 × 融合一致性”决定，而非由位宽单独决定；层数越深、离群值越频繁的模型，越需要更细的块或混合位宽策略。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-57\">五十七 · 不适用的边界：格式语义不等于吞吐收益</h3>\n<p>必须明确一条边界：MX 是格式定义与量化语义，不是性能保证。论文材料明确未给出端到端吞吐、显存实测与精度对比数字，因此把格式定义直接等同于推理加速是错的。不适用的情况有三类。第一类是小 batch、低并发的解码负载：此时瓶颈在访存延迟而非带宽，低精度格式减少的是字节数，但每次 MMA 的固定开销与缩放因子读取的额外指令占比上升，净收益可能为负。第二类是激活动态范围极端不均的负载：块内离群值拉高缩放后，其余元素的有效精度下降，若模型本身对激活精度敏感（如某些归一化后的残差路径），低位宽会直接反映为输出质量退化。第三类是算子未被块缩放语义覆盖的路径：注意力中的 softmax、逐元素激活函数若仍走全局缩放或逐张量缩放，整条链路的数值语义不一致，低精度收益被局部高精度路径抵消。</p>\n<p>工程判断落在具体机制上：迁移 MX 到新模型时，先做三件事——确认块切分轴与 MMA 的 K 维对齐、确认缩放因子编码与算子舍入语义逐位一致、确认目标负载的瓶颈在带宽而非延迟。三者任一不满足，低精度格式的收益就不成立。格式族为 NVFP4 等硬件块缩放路径提供了语义基础，但语义基础到端到端吞吐之间隔着算子融合、布局对齐与调度策略，这段距离只能靠逐层的误差探测与带宽核算来填，不能靠格式定义本身跨过去。</p>\n\n<h3 id=\"paper-microscaling-data-formats-for-deep-l-2023-sec-58\">五十八 · 块缩放格式迁移到别的负载时，先看离群值结构与块边界是否对齐</h3>\n<p>把 MX 格式搬到新模型上，第一件要改的不是位宽，而是块大小与统计轴的匹配。论文的语义是固定块、块内取绝对值最大值推导缩放因子，因此块边界一旦与离群值结构错位，缩放因子就被单个大值拉高，同块其余元素的有效尾数被压缩。判断准则可以写成块内动态范围比：若某块满足 <span class=\"formula\">$$\\frac{\\max_{j\\in B}|x_j|}{\\mathrm{median}_{j\\in B}|x_j|}\\gg 1$$</span>，则该块的低精度元素基本是在为离群值陪跑。工程上这意味着迁移到激活长尾明显的领域（注意力 QK 输出、归一化前的残差）时，要么缩小块以提高统计粒度、接受元数据比例上升带来的显存与带宽代价，要么把离群通道单独走更高位宽通路。块大小减半，缩放因子数量翻倍，反量化时每元素摊到的元数据读取与解码开销随之上升，这是直接的带宽与指令代价，不是免费的精度补偿。</p>\n<p>第二处要改的是算子融合路径。MX 的语义要求矩阵乘按块读取缩放并在累加中融合反量化；迁到新框架时若算子只接受整张量缩放，量化层与算子层语义就会脱节，反量化误差在多层间累积。注意力里的 QK 与 PV 乘同样沿用块缩放，KV 缓存若以低精度块存储，则缓存写入时的重新量化与读取时的反量化都要与同一套舍入语义对齐，否则同一段 KV 在不同层被反复量化会放大偏差。这里的系统代价是可测的：融合反量化省掉一次显式物化，但块级缩放读取增加了张量核心外的标量负载，块越小这一项越突出。</p>\n<p>不适用与规模上限要讲清楚。整张量共享缩放的场景（权重分布平坦、无显著离群）用 MX 收益有限，元数据反而增加显存占用；逐元素缩放精度更好但元数据开销不可接受，MX 只是两者之间的折中，不是普适最优。论文材料未给出端到端吞吐、显存实测与精度对比数字，块大小与位宽组合的精度损失边界也未量化，因此不能把格式定义直接等同于部署收益。规模上限落在两处：一是块内离群值统计无法在格式层消除，只能靠更细粒度或混合精度绕开；二是缩放因子编码与舍入语义必须与硬件张量核心的块缩放支持严格一致，任何实现偏差都会随层数放大。迁移判断应落在“离群值是否块内局部化、算子是否支持块级融合反量化”这两个可验证问题上，而不是位宽数字本身。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Microscaling Data Formats </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">for Deep Lear…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Microscaling Data Forma… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>论文给出格式定义与数值语义分析，材料未提供具体数据集上的吞吐或精度数字，相…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，块大小与元素位宽的组合影响未给出具体数值。</td></tr><tr><td>局限</td><td>材料未给出硬件实测与端到端服务化数据，块大小与位宽组合的精度损失边界未量化…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-microscaling-data-formats-for-deep-l-2023 · 共 9 个片段</p>\n";break;}}})();
